// Accepts {"url":"..."} or {"urls":[...]} plus an optional method.
// Mode: Run Once for All Items.

const b = ($input.first().json || {}).body || $input.first().json || {};
let urls = b.urls ?? b.url;
if (typeof urls === 'string') urls = [urls];
if (!Array.isArray(urls) || !urls.length) {
  throw new Error('POST {"url":"https://...","method":"HEAD"}');
}
const method = String(b.method || 'HEAD').toUpperCase();
// preset=image sends image-oriented headers with a Pinterest referer
// (right for i.pinimg.com, wrong for normal web pages, which some
// edges answer with 400). preset=browser sends plain browser headers.
const preset = String(b.preset || 'image').toLowerCase();
return urls.slice(0, 10).map((u) => ({ json: { url: String(u), method, preset } }));

// Mode: Run Once for All Items.
const asked = $('Read Request').all().map((i) => i.json);
return $input.all().map((it, i) => {
  const j = it.json || {};
  const h = j.headers || {};
  return { json: {
    url: asked[i]?.url || '',
    method: asked[i]?.method || '',
    status: j.statusCode ?? null,
    content_type: h['content-type'] || null,
    content_length: Number(h['content-length'] || 0) || null,
  } };
});

// Flattens the config table into one object so later nodes can read settings
// as $('Config').first().json.SLOTS instead of searching rows.
// Defaults are applied for any key missing from the table, so the workflow
// still runs on a fresh install. Mode: Run Once for All Items.

const DEFAULTS = {
  TIMEZONE: 'Europe/Belgrade',
  SLOTS: '10:00,15:00,20:00',
  TEXT_MODE: 'pinterest',
  REPOST_AFTER_DAYS: '60',
  SCHEDULE_HORIZON_DAYS: '14',
  MAX_QUEUE_PER_RUN: '60',
  RETRY_DELAY_MINUTES: '30',
  EXTRA_HASHTAGS: '',
  POST_TEXT_MAX_CHARS: '600',
  FB_PAGE_ID: '',
  PIN_RESOLVE_MAX_PER_RUN: '10',
  RESOLVE_THROTTLE_MS: '2000',
  RESOLVE_MAX_ATTEMPTS: '3',
  DRY_RUN: 'true',
  MAX_PUBLISH_PER_RUN: '20',
  FB_API_VERSION: 'v21.0',
  AUTH_MODE: 'oauth',
};

const cfg = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key) cfg[String(r.key)] = r.value == null ? '' : String(r.value);
}

// Typed views, so consumers never re-parse strings.
cfg._slots = String(cfg.SLOTS).split(',').map((s) => s.trim()).filter(Boolean);
cfg._repost_after_days = Number(cfg.REPOST_AFTER_DAYS) || 0;
cfg._resolve_max = Math.max(1, Number(cfg.PIN_RESOLVE_MAX_PER_RUN) || 10);
cfg._throttle_ms = Math.max(0, Number(cfg.RESOLVE_THROTTLE_MS) || 0);
cfg._resolve_max_attempts = Math.max(1, Number(cfg.RESOLVE_MAX_ATTEMPTS) || 3);
cfg._horizon_days = Math.max(1, Number(cfg.SCHEDULE_HORIZON_DAYS) || 14);
cfg._max_queue = Math.max(1, Number(cfg.MAX_QUEUE_PER_RUN) || 60);
cfg._text_max = Math.max(80, Number(cfg.POST_TEXT_MAX_CHARS) || 600);
cfg._retry_delay_minutes = Math.max(1, Number(cfg.RETRY_DELAY_MINUTES) || 30);
cfg._max_publish = Math.max(1, Number(cfg.MAX_PUBLISH_PER_RUN) || 20);
// Anything but an explicit "false" keeps the safety on.
cfg._dry_run = String(cfg.DRY_RUN).trim().toLowerCase() !== 'false';
// Anything other than an explicit "token" means the OAuth login path.
cfg._auth_mode = String(cfg.AUTH_MODE).trim().toLowerCase() === 'token'
  ? 'token' : 'oauth';

return [{ json: cfg }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Boards').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Items').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

/**
 * Board input normalization: turn whatever the user types into a username,
 * a board slug and an RSS URL.
 *
 * Used by the feed probe and by Workflow D's "add board" form, so a board
 * added through the UI and a board tested by hand always produce the same
 * rss_url. Part of the Pinterest source layer.
 *
 * The forms accept sloppy input on purpose - a pasted board URL, a profile
 * URL, an @handle, a display name - because the user fills them in by hand.
 */

const PINTEREST_HOST_RE = /^https?:\/\/(?:[a-z0-9-]+\.)?pinterest\.[a-z.]+\//i;

/** "@SmartlyDigit", "pinterest.com/smartlydigit/", "SmartlyDigit" -> "smartlydigit" */
function normalizeUsername(input) {
  let s = String(input || '').trim();
  if (!s) return '';
  if (PINTEREST_HOST_RE.test(s)) {
    const m = s.replace(PINTEREST_HOST_RE, '').split(/[/?#]/).filter(Boolean);
    s = m[0] || '';
  }
  s = s.replace(/^@/, '').trim().toLowerCase();
  // Pinterest usernames: letters, digits, underscore; no spaces.
  s = s.replace(/[^a-z0-9_]/g, '');
  return s;
}

/** "Printable Wall Art!" -> "printable-wall-art"; already-slug passes through. */
function slugify(input) {
  return String(input || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

/**
 * Pull username and/or slug out of a pasted Pinterest URL.
 * Returns {} when the string is not a Pinterest URL.
 */
function fromPinterestUrl(input) {
  const s = String(input || '').trim();
  if (!PINTEREST_HOST_RE.test(s)) return {};
  const parts = s.replace(PINTEREST_HOST_RE, '').split(/[?#]/)[0]
    .split('/').filter(Boolean);
  if (!parts.length) return {};
  const out = { username: normalizeUsername(parts[0]) };
  if (parts[1]) {
    // Tolerate a pasted ".../board.rss" too.
    out.board_slug = slugify(parts[1].replace(/\.rss$/i, ''));
  }
  // /pin/12345/ is a pin, not a board - do not mistake it for a slug.
  if (out.board_slug === 'pin' || /^\d+$/.test(out.board_slug || '')) {
    delete out.board_slug;
  }
  return out;
}

/**
 * Resolve the two form fields into a board definition.
 *
 * Either field may carry a full URL; a URL in the board field wins, because
 * that is what a user pasting a board link expects.
 *
 * @returns {{ok:true, username, board_slug, rss_url}|{ok:false, error}}
 */
function resolveBoard(usernameInput, boardInput) {
  const fromBoard = fromPinterestUrl(boardInput);
  const fromUser = fromPinterestUrl(usernameInput);

  const username = fromBoard.username
    || fromUser.username
    || normalizeUsername(usernameInput);

  const board_slug = fromBoard.board_slug
    || (fromBoard.username ? '' : slugify(boardInput))
    || fromUser.board_slug
    || '';

  if (!username) {
    return { ok: false, error:
      'Could not read a Pinterest username. Enter it as it appears in your '
      + 'profile URL (pinterest.com/USERNAME), or paste the profile URL.' };
  }
  if (!board_slug) {
    return { ok: false, error:
      'Could not read a board slug. Enter the last part of the board URL '
      + '(pinterest.com/username/BOARD-SLUG), or paste the board URL.' };
  }
  return { ok: true, username, board_slug, rss_url: buildRssUrl(username, board_slug) };
}

function buildRssUrl(username, board_slug) {
  return `https://www.pinterest.com/${username}/${board_slug}.rss`;
}

/**
 * Workflow D - control surface logic. Pure functions, no n8n, no clock.
 *
 * Every view and action the operator has: read the queue, look a listing up,
 * toggle a board, add one, reschedule or drop an entry, and produce the
 * copy-paste list for posting by hand when the Graph API is not available.
 *
 * Source-agnostic: works from boards / items / schedule keyed on
 * etsy_listing_id.
 */

// resolveBoard comes from the inlined board-url module above.

const DAY_MS = 86_400_000;
const PENDING = new Set(['queued', 'posting', 'scheduled']);

function parseList(v) {
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === 'string' && v.trim()) {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p.map(String);
      if (typeof p === 'string') return [p];
    } catch { return [v]; }
  }
  return [];
}

/** Accepts an Etsy URL in any shape, or a bare listing id. */
function parseListingRef(input) {
  const s = String(input || '').trim();
  if (!s) return '';
  const m = s.match(/listing\/(\d{6,15})/i);
  if (m) return m[1];
  if (/^\d{6,15}$/.test(s)) return s;
  return '';
}

/** Wall-clock rendering in the operator's zone, for every view. */
function localTime(iso, timeZone) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return String(iso || '');
  return new Intl.DateTimeFormat('en-GB', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date(t)).replace(',', '');
}

function localDate(iso, timeZone) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '';
  return new Intl.DateTimeFormat('en-CA', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(new Date(t));
}

function indexItems(items) {
  const byId = new Map();
  for (const it of items) {
    if (it && it.etsy_listing_id) byId.set(String(it.etsy_listing_id), it);
  }
  return byId;
}

// ------------------------------------------------------------------- views

/**
 * The posts due in a given local day, ready to paste by hand.
 * This is the no-API path: everything decided, nothing sent.
 */
function todaysPosts({ scheduleRows = [], items = [], timeZone = 'UTC',
                       nowMs = Date.now(), dayOffset = 0 } = {}) {
  const byId = indexItems(items);
  const target = localDate(new Date(nowMs + dayOffset * DAY_MS).toISOString(), timeZone);

  const due = scheduleRows
    .filter((r) => PENDING.has(String(r.status || '')))
    .filter((r) => localDate(r.scheduled_at, timeZone) === target)
    .sort((a, b) => String(a.scheduled_at).localeCompare(String(b.scheduled_at)));

  return {
    date: target,
    timezone: timeZone,
    count: due.length,
    posts: due.map((r) => {
      const it = byId.get(String(r.etsy_listing_id)) || {};
      return {
        row_id: r.id,
        time: localTime(r.scheduled_at, timeZone).slice(-5),
        scheduled_at: r.scheduled_at,
        status: r.status,
        etsy_listing_id: r.etsy_listing_id,
        board_slug: r.board_slug,
        image_url: it.image_url || '',
        post_text: r.post_text || '',
        missing_item: !byId.has(String(r.etsy_listing_id)),
      };
    }),
  };
}

/** Grouped queue for the next N days. */
function queueView({ scheduleRows = [], items = [], timeZone = 'UTC',
                     nowMs = Date.now(), days = 7 } = {}) {
  const byId = indexItems(items);
  const until = nowMs + days * DAY_MS;

  const rows = scheduleRows
    .filter((r) => PENDING.has(String(r.status || '')))
    .filter((r) => {
      const t = Date.parse(r.scheduled_at);
      return Number.isFinite(t) && t <= until;
    })
    .sort((a, b) => String(a.scheduled_at).localeCompare(String(b.scheduled_at)));

  const byDay = new Map();
  for (const r of rows) {
    const d = localDate(r.scheduled_at, timeZone);
    if (!byDay.has(d)) byDay.set(d, []);
    const it = byId.get(String(r.etsy_listing_id)) || {};
    byDay.get(d).push({
      row_id: r.id,
      time: localTime(r.scheduled_at, timeZone).slice(-5),
      status: r.status,
      etsy_listing_id: r.etsy_listing_id,
      board_slug: r.board_slug,
      title: String(it.title || '').slice(0, 70),
    });
  }

  return {
    days,
    timezone: timeZone,
    total: rows.length,
    by_day: [...byDay.entries()].map(([date, entries]) => ({ date, entries })),
  };
}

/** Everything known about one listing. */
function checkListing({ ref = '', scheduleRows = [], items = [],
                        timeZone = 'UTC' } = {}) {
  const id = parseListingRef(ref);
  if (!id) {
    return { ok: false,
      error: `Could not read a listing id from "${ref}". Paste the Etsy URL `
        + 'or just the numeric id.' };
  }

  const item = indexItems(items).get(id) || null;
  const rows = scheduleRows.filter((r) => String(r.etsy_listing_id) === id);
  const row = rows.sort((a, b) => Number(b.id || 0) - Number(a.id || 0))[0] || null;

  let verdict;
  if (!row) {
    verdict = item
      ? 'not scheduled'
      : 'unknown - no items row either, so the sync has never seen this listing';
  } else if (PENDING.has(String(row.status))) {
    verdict = `already scheduled for ${localTime(row.scheduled_at, timeZone)} `
      + `(${timeZone})`
      + (row.status === 'scheduled' ? ' - already handed to Facebook' : '')
      + (row.status === 'posting' ? ' - being published right now' : '');
  } else if (row.status === 'posted') {
    verdict = `posted on ${localTime(row.posted_at || row.scheduled_at, timeZone)}`;
  } else if (row.status === 'failed') {
    verdict = `failed after ${row.attempts || 0} attempt(s): ${row.error || 'no error recorded'}`;
  } else if (row.status === 'skipped') {
    verdict = 'skipped - its boards were disabled';
  } else {
    verdict = `unknown status "${row.status}"`;
  }

  return {
    ok: true,
    etsy_listing_id: id,
    etsy_url: item ? item.etsy_url : `https://www.etsy.com/listing/${id}`,
    verdict,
    in_items: Boolean(item),
    title: item ? String(item.title || '').slice(0, 120) : '',
    boards: item ? parseList(item.board_slugs) : [],
    image_url: item ? item.image_url || '' : '',
    row: row ? {
      row_id: row.id, status: row.status,
      scheduled_at: row.scheduled_at, scheduled_local: localTime(row.scheduled_at, timeZone),
      posted_at: row.posted_at, attempts: row.attempts, error: row.error,
      fb_post_id: row.fb_post_id,
    } : null,
    can_queue_now: Boolean(item) && !row,
  };
}

/** Board list with what each one is actually contributing. */
function boardsView({ boards = [], items = [], scheduleRows = [] } = {}) {
  const pendingByBoard = {};
  for (const r of scheduleRows) {
    if (!PENDING.has(String(r.status || ''))) continue;
    const b = String(r.board_slug || '');
    pendingByBoard[b] = (pendingByBoard[b] || 0) + 1;
  }
  const itemsByBoard = {};
  for (const it of items) {
    for (const b of parseList(it.board_slugs)) {
      itemsByBoard[b] = (itemsByBoard[b] || 0) + 1;
    }
  }

  return {
    count: boards.length,
    boards: boards
      .slice()
      .sort((a, b) => (Number(b.priority) || 0) - (Number(a.priority) || 0)
        || String(a.board_slug).localeCompare(String(b.board_slug)))
      .map((b) => ({
        board_slug: b.board_slug,
        name: b.name || b.board_slug,
        enabled: b.enabled === true,
        priority: Number(b.priority) || 0,
        rss_url: b.rss_url,
        last_synced_at: b.last_synced_at || null,
        listings: itemsByBoard[b.board_slug] || 0,
        queued_now: pendingByBoard[b.board_slug] || 0,
      })),
  };
}

// ----------------------------------------------------------------- actions

/**
 * Turning a board off must not silently strand its queue, and turning it back
 * on must undo exactly that.
 *
 * Disabling: queued rows whose listing belongs ONLY to disabled boards become
 * skipped. A listing that also sits on an enabled board keeps its slot.
 * Enabling: skipped rows whose listing now has an enabled board go back to
 * queued.
 */
function planCascade({ boards = [], items = [], scheduleRows = [] } = {}) {
  const enabled = new Set(
    boards.filter((b) => b.enabled === true).map((b) => String(b.board_slug))
  );
  const byId = indexItems(items);
  const updates = [];

  for (const r of scheduleRows) {
    const status = String(r.status || '');
    const it = byId.get(String(r.etsy_listing_id));
    if (!it) continue;
    const hasEnabled = parseList(it.board_slugs).some((b) => enabled.has(b));

    if (PENDING.has(status) && !hasEnabled) {
      updates.push({ row_id: r.id, etsy_listing_id: r.etsy_listing_id,
        status: 'skipped',
        error: 'Every board for this listing is disabled.',
        reason: 'board_disabled' });
    } else if (status === 'skipped' && hasEnabled) {
      updates.push({ row_id: r.id, etsy_listing_id: r.etsy_listing_id,
        status: 'queued', error: '', reason: 'board_re_enabled' });
    }
  }

  return {
    updates,
    summary: {
      to_skip: updates.filter((u) => u.reason === 'board_disabled').length,
      to_restore: updates.filter((u) => u.reason === 'board_re_enabled').length,
      enabled_boards: [...enabled],
    },
  };
}

/** Validate an "add board" request into a row ready to insert. */
function planAddBoard({ username = '', board = '', name = '', priority = 0,
                        existing = [] } = {}) {
  const r = resolveBoard(username, board);
  if (!r.ok) return { ok: false, error: r.error };

  if (existing.some((b) => String(b.board_slug) === r.board_slug)) {
    return { ok: false,
      error: `Board "${r.board_slug}" is already in the table. Use the toggle `
        + 'action to enable or disable it.' };
  }

  return {
    ok: true,
    row: {
      board_slug: r.board_slug,
      name: String(name || '').trim() || r.board_slug,
      rss_url: r.rss_url,
      // New boards start disabled on purpose: sync collects their pins, and
      // nothing is published until you turn them on deliberately.
      enabled: false,
      priority: Number(priority) || 0,
      last_synced_at: null,
    },
    note: `Added disabled. Run "A - Sync Boards" to collect its pins, then `
      + 'enable it when you are ready to post from it.',
  };
}

/** Validate a reschedule/remove request against the actual row. */
function planEntryAction({ action = '', rowId = '', newTime = '',
                           scheduleRows = [], timeZone = 'UTC',
                           nowMs = Date.now() } = {}) {
  const id = String(rowId || '').trim();
  const row = scheduleRows.find((r) => String(r.id) === id);
  if (!row) {
    return { ok: false,
      error: `No schedule entry with id ${id || '(empty)'}. The queue view `
        + 'lists the ids.' };
  }

  if (action === 'remove') {
    if (row.status === 'scheduled') {
      return { ok: false,
        error: `Entry ${id} was already handed to Facebook (fb_post_id `
          + `${row.fb_post_id || 'unknown'}). Removing the row here would NOT `
          + 'unpublish it - delete the scheduled post in Meta Business Suite '
          + 'first, then remove the row.' };
    }
    return { ok: true, action: 'remove', row_id: row.id,
      note: `Entry ${id} for listing ${row.etsy_listing_id} will be deleted. `
        + 'The listing becomes eligible for queueing again on the next run of '
        + 'Workflow B.' };
  }

  // reschedule
  const t = Date.parse(newTime);
  if (!Number.isFinite(t)) {
    return { ok: false,
      error: `Could not read "${newTime}" as a time. Use an ISO timestamp `
        + 'like 2026-10-05T14:00:00Z, or 2026-10-05 16:00 for local time.' };
  }
  if (t <= nowMs) {
    return { ok: false,
      error: `${localTime(new Date(t).toISOString(), timeZone)} is in the past.` };
  }
  if (row.status === 'scheduled') {
    return { ok: false,
      error: `Entry ${id} is already scheduled on Facebook. Change the time in `
        + 'Meta Business Suite, or remove it there and reschedule here.' };
  }

  return {
    ok: true,
    action: 'reschedule',
    row_id: row.id,
    scheduled_at: new Date(t).toISOString(),
    // A failed row being rescheduled is a fresh start, so clear the failure.
    status: 'queued',
    note: `Entry ${id} moved to ${localTime(new Date(t).toISOString(), timeZone)} `
      + `(${timeZone}) and reset to queued.`,
  };
}

// ---------------------------------------------------------------- n8n glue
// Workflow D: read the form, answer everything read-only immediately, and
// validate everything that writes before a single table is touched.
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const tz = cfg.TIMEZONE;
const boards = $('Load Boards').all().map((i) => i.json || {}).filter((b) => b.board_slug);
const items = $('Load Items').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);
const scheduleRows = $('Load Schedule').all().map((i) => i.json || {})
  .filter((r) => r.etsy_listing_id);

const f = $('Control Form').first().json;
const get = (label) => String(f[label] ?? '').trim();

const ACTIONS = {
  "Today's posts (copy-paste list)": 'today',
  "Tomorrow's posts (copy-paste list)": 'tomorrow',
  'Queue for the next 7 days': 'queue7',
  'Check a listing': 'check',
  'Boards: show all': 'boards',
  'Board: enable': 'enable',
  'Board: disable': 'disable',
  'Board: add a new one': 'addboard',
  'Entry: reschedule': 'reschedule',
  'Entry: remove': 'remove',
};

const label = get('Action');
const action = ACTIONS[label] || '';

const answer = (title, text, extra = {}) => [{ json: {
  _kind: 'answer', title, text, ...extra } }];

if (!action) {
  return answer('Pick an action',
    `"${label}" is not one of the actions. Choose one from the dropdown.`);
}

// ------------------------------------------------------- copy-paste lists
//
// This is the no-API path: everything is decided here - what, when, which
// image, what caption - and you paste it into Meta Business Suite yourself.
const renderPosts = (view, heading) => {
  if (!view.count) {
    return answer(heading,
      `Nothing scheduled for ${view.date} (${view.timezone}).\n\n`
      + 'Run "B - Build Schedule" to fill the queue, and check that at least '
      + 'one board is enabled.');
  }
  const blocks = view.posts.map((p, i) => [
    `----- ${i + 1} of ${view.count} -----`,
    `TIME (${view.timezone}): ${p.time}`,
    `IMAGE: ${p.image_url || '(none - do not post this one)'}`,
    p.missing_item ? 'WARNING: the items row for this listing is gone.' : '',
    '',
    'CAPTION (copy everything between the lines):',
    '---8<---',
    p.post_text,
    '---8<---',
    '',
    `entry id ${p.row_id} | listing ${p.etsy_listing_id} | board ${p.board_slug}`,
  ].filter(Boolean).join('\n'));

  return answer(`${heading} - ${view.count} post(s)`,
    [`${view.date} (${view.timezone})`, '',
      'Paste each caption into Meta Business Suite and attach the image at '
      + 'the IMAGE url, then set the time shown.', '',
      ...blocks,
    ].join('\n'),
    { date: view.date, count: view.count });
};

if (action === 'today') {
  return renderPosts(todaysPosts({ scheduleRows, items, timeZone: tz }), 'Posts due today');
}
if (action === 'tomorrow') {
  return renderPosts(
    todaysPosts({ scheduleRows, items, timeZone: tz, dayOffset: 1 }), 'Posts due tomorrow');
}

if (action === 'queue7') {
  const v = queueView({ scheduleRows, items, timeZone: tz, days: 7 });
  if (!v.total) {
    return answer('Queue is empty',
      'Nothing is queued for the next 7 days. Run "B - Build Schedule", and '
      + 'check that a board is enabled.');
  }
  const lines = v.by_day.map((d) => [
    `${d.date}`,
    ...d.entries.map((e) =>
      `   ${e.time}  #${e.row_id}  ${e.status.padEnd(9)} ${e.etsy_listing_id}  `
      + `[${e.board_slug}]  ${e.title}`),
  ].join('\n'));
  return answer(`Queue - ${v.total} entr${v.total === 1 ? 'y' : 'ies'} in 7 days`,
    [`All times ${v.timezone}. The # is the entry id, for reschedule/remove.`,
      '', ...lines].join('\n'));
}

if (action === 'check') {
  const r = checkListing({ ref: get('Etsy URL or listing id'), scheduleRows, items,
    timeZone: tz });
  if (!r.ok) return answer('Could not read that listing', r.error);
  return answer(`Listing ${r.etsy_listing_id}`,
    [`${r.verdict.toUpperCase()}`, '',
      `Etsy:   ${r.etsy_url}`,
      `Title:  ${r.title || '(not in items)'}`,
      `Boards: ${r.boards.join(', ') || '(none)'}`,
      `Image:  ${r.image_url || '(none)'}`,
      '',
      r.row
        ? `Entry #${r.row.row_id} | status ${r.row.status}`
          + ` | slot ${r.row.scheduled_local}`
          + (r.row.attempts ? ` | attempts ${r.row.attempts}` : '')
          + (r.row.error ? `\nError: ${r.row.error}` : '')
          + (r.row.fb_post_id ? `\nFacebook post id: ${r.row.fb_post_id}` : '')
        : r.can_queue_now
          ? 'No schedule entry. The next run of "B - Build Schedule" will '
            + 'queue it, provided one of its boards is enabled.'
          : 'Not in items either - run "A - Sync Boards" first.',
    ].join('\n'));
}

if (action === 'boards') {
  const v = boardsView({ boards, items, scheduleRows });
  if (!v.count) {
    return answer('No boards yet', 'Use "Board: add a new one" to add the first.');
  }
  const lines = v.boards.map((b) =>
    `${b.enabled ? '[ON ]' : '[off]'} ${b.board_slug}`
    + `\n        name ${b.name} | priority ${b.priority}`
    + `\n        ${b.listings} listing(s) | ${b.queued_now} queued now`
    + `\n        last sync ${b.last_synced_at ? localTime(b.last_synced_at, tz) : 'never'}`
    + `\n        ${b.rss_url}`);
  return answer(`Boards - ${v.count}`,
    ['[ON] means its listings may be published. [off] still collects pins.',
      '', ...lines].join('\n'));
}

// -------------------------------------------------------- write actions
// Validated here; the write itself happens in the branch downstream.

if (action === 'enable' || action === 'disable') {
  const slug = get('Board slug (for enable / disable)');
  if (!slug) {
    return answer('Which board?',
      'Fill in "Board slug (for enable / disable)". Use "Boards: show all" to '
      + 'see the slugs.');
  }
  const board = boards.find((b) => String(b.board_slug) === slug);
  if (!board) {
    return answer('No such board',
      `There is no board "${slug}". Existing: `
      + boards.map((b) => b.board_slug).join(', ') || '(none)');
  }
  const want = action === 'enable';
  if (board.enabled === want) {
    return answer('Nothing to change',
      `Board "${slug}" is already ${want ? 'enabled' : 'disabled'}.`);
  }
  return [{ json: {
    _kind: 'toggle', board_slug: slug, enabled: want,
    board_name: board.name || slug,
  } }];
}

if (action === 'addboard') {
  const plan = planAddBoard({
    username: get('New board: Pinterest username'),
    board: get('New board: slug, name or pasted URL'),
    name: get('New board: display name'),
    priority: get('New board: priority'),
    existing: boards,
  });
  if (!plan.ok) return answer('Could not add that board', plan.error);
  return [{ json: { _kind: 'addboard', ...plan.row, note: plan.note } }];
}

if (action === 'reschedule' || action === 'remove') {
  const plan = planEntryAction({
    action,
    rowId: get('Entry id (the # from the queue view)'),
    newTime: get('New time (e.g. 2026-10-05T14:00:00Z)'),
    scheduleRows, timeZone: tz,
  });
  if (!plan.ok) return answer('Could not do that', plan.error);
  return [{ json: { _kind: plan.action, ...plan } }];
}

return answer('Not implemented', `Action "${action}" has no handler.`);

/**
 * Board input normalization: turn whatever the user types into a username,
 * a board slug and an RSS URL.
 *
 * Used by the feed probe and by Workflow D's "add board" form, so a board
 * added through the UI and a board tested by hand always produce the same
 * rss_url. Part of the Pinterest source layer.
 *
 * The forms accept sloppy input on purpose - a pasted board URL, a profile
 * URL, an @handle, a display name - because the user fills them in by hand.
 */

const PINTEREST_HOST_RE = /^https?:\/\/(?:[a-z0-9-]+\.)?pinterest\.[a-z.]+\//i;

/** "@SmartlyDigit", "pinterest.com/smartlydigit/", "SmartlyDigit" -> "smartlydigit" */
function normalizeUsername(input) {
  let s = String(input || '').trim();
  if (!s) return '';
  if (PINTEREST_HOST_RE.test(s)) {
    const m = s.replace(PINTEREST_HOST_RE, '').split(/[/?#]/).filter(Boolean);
    s = m[0] || '';
  }
  s = s.replace(/^@/, '').trim().toLowerCase();
  // Pinterest usernames: letters, digits, underscore; no spaces.
  s = s.replace(/[^a-z0-9_]/g, '');
  return s;
}

/** "Printable Wall Art!" -> "printable-wall-art"; already-slug passes through. */
function slugify(input) {
  return String(input || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

/**
 * Pull username and/or slug out of a pasted Pinterest URL.
 * Returns {} when the string is not a Pinterest URL.
 */
function fromPinterestUrl(input) {
  const s = String(input || '').trim();
  if (!PINTEREST_HOST_RE.test(s)) return {};
  const parts = s.replace(PINTEREST_HOST_RE, '').split(/[?#]/)[0]
    .split('/').filter(Boolean);
  if (!parts.length) return {};
  const out = { username: normalizeUsername(parts[0]) };
  if (parts[1]) {
    // Tolerate a pasted ".../board.rss" too.
    out.board_slug = slugify(parts[1].replace(/\.rss$/i, ''));
  }
  // /pin/12345/ is a pin, not a board - do not mistake it for a slug.
  if (out.board_slug === 'pin' || /^\d+$/.test(out.board_slug || '')) {
    delete out.board_slug;
  }
  return out;
}

/**
 * Resolve the two form fields into a board definition.
 *
 * Either field may carry a full URL; a URL in the board field wins, because
 * that is what a user pasting a board link expects.
 *
 * @returns {{ok:true, username, board_slug, rss_url}|{ok:false, error}}
 */
function resolveBoard(usernameInput, boardInput) {
  const fromBoard = fromPinterestUrl(boardInput);
  const fromUser = fromPinterestUrl(usernameInput);

  const username = fromBoard.username
    || fromUser.username
    || normalizeUsername(usernameInput);

  const board_slug = fromBoard.board_slug
    || (fromBoard.username ? '' : slugify(boardInput))
    || fromUser.board_slug
    || '';

  if (!username) {
    return { ok: false, error:
      'Could not read a Pinterest username. Enter it as it appears in your '
      + 'profile URL (pinterest.com/USERNAME), or paste the profile URL.' };
  }
  if (!board_slug) {
    return { ok: false, error:
      'Could not read a board slug. Enter the last part of the board URL '
      + '(pinterest.com/username/BOARD-SLUG), or paste the board URL.' };
  }
  return { ok: true, username, board_slug, rss_url: buildRssUrl(username, board_slug) };
}

function buildRssUrl(username, board_slug) {
  return `https://www.pinterest.com/${username}/${board_slug}.rss`;
}

/**
 * Workflow D - control surface logic. Pure functions, no n8n, no clock.
 *
 * Every view and action the operator has: read the queue, look a listing up,
 * toggle a board, add one, reschedule or drop an entry, and produce the
 * copy-paste list for posting by hand when the Graph API is not available.
 *
 * Source-agnostic: works from boards / items / schedule keyed on
 * etsy_listing_id.
 */

// resolveBoard comes from the inlined board-url module above.

const DAY_MS = 86_400_000;
const PENDING = new Set(['queued', 'posting', 'scheduled']);

function parseList(v) {
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === 'string' && v.trim()) {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p.map(String);
      if (typeof p === 'string') return [p];
    } catch { return [v]; }
  }
  return [];
}

/** Accepts an Etsy URL in any shape, or a bare listing id. */
function parseListingRef(input) {
  const s = String(input || '').trim();
  if (!s) return '';
  const m = s.match(/listing\/(\d{6,15})/i);
  if (m) return m[1];
  if (/^\d{6,15}$/.test(s)) return s;
  return '';
}

/** Wall-clock rendering in the operator's zone, for every view. */
function localTime(iso, timeZone) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return String(iso || '');
  return new Intl.DateTimeFormat('en-GB', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', hour12: false,
  }).format(new Date(t)).replace(',', '');
}

function localDate(iso, timeZone) {
  const t = Date.parse(iso);
  if (!Number.isFinite(t)) return '';
  return new Intl.DateTimeFormat('en-CA', {
    timeZone, year: 'numeric', month: '2-digit', day: '2-digit',
  }).format(new Date(t));
}

function indexItems(items) {
  const byId = new Map();
  for (const it of items) {
    if (it && it.etsy_listing_id) byId.set(String(it.etsy_listing_id), it);
  }
  return byId;
}

// ------------------------------------------------------------------- views

/**
 * The posts due in a given local day, ready to paste by hand.
 * This is the no-API path: everything decided, nothing sent.
 */
function todaysPosts({ scheduleRows = [], items = [], timeZone = 'UTC',
                       nowMs = Date.now(), dayOffset = 0 } = {}) {
  const byId = indexItems(items);
  const target = localDate(new Date(nowMs + dayOffset * DAY_MS).toISOString(), timeZone);

  const due = scheduleRows
    .filter((r) => PENDING.has(String(r.status || '')))
    .filter((r) => localDate(r.scheduled_at, timeZone) === target)
    .sort((a, b) => String(a.scheduled_at).localeCompare(String(b.scheduled_at)));

  return {
    date: target,
    timezone: timeZone,
    count: due.length,
    posts: due.map((r) => {
      const it = byId.get(String(r.etsy_listing_id)) || {};
      return {
        row_id: r.id,
        time: localTime(r.scheduled_at, timeZone).slice(-5),
        scheduled_at: r.scheduled_at,
        status: r.status,
        etsy_listing_id: r.etsy_listing_id,
        board_slug: r.board_slug,
        image_url: it.image_url || '',
        post_text: r.post_text || '',
        missing_item: !byId.has(String(r.etsy_listing_id)),
      };
    }),
  };
}

/** Grouped queue for the next N days. */
function queueView({ scheduleRows = [], items = [], timeZone = 'UTC',
                     nowMs = Date.now(), days = 7 } = {}) {
  const byId = indexItems(items);
  const until = nowMs + days * DAY_MS;

  const rows = scheduleRows
    .filter((r) => PENDING.has(String(r.status || '')))
    .filter((r) => {
      const t = Date.parse(r.scheduled_at);
      return Number.isFinite(t) && t <= until;
    })
    .sort((a, b) => String(a.scheduled_at).localeCompare(String(b.scheduled_at)));

  const byDay = new Map();
  for (const r of rows) {
    const d = localDate(r.scheduled_at, timeZone);
    if (!byDay.has(d)) byDay.set(d, []);
    const it = byId.get(String(r.etsy_listing_id)) || {};
    byDay.get(d).push({
      row_id: r.id,
      time: localTime(r.scheduled_at, timeZone).slice(-5),
      status: r.status,
      etsy_listing_id: r.etsy_listing_id,
      board_slug: r.board_slug,
      title: String(it.title || '').slice(0, 70),
    });
  }

  return {
    days,
    timezone: timeZone,
    total: rows.length,
    by_day: [...byDay.entries()].map(([date, entries]) => ({ date, entries })),
  };
}

/** Everything known about one listing. */
function checkListing({ ref = '', scheduleRows = [], items = [],
                        timeZone = 'UTC' } = {}) {
  const id = parseListingRef(ref);
  if (!id) {
    return { ok: false,
      error: `Could not read a listing id from "${ref}". Paste the Etsy URL `
        + 'or just the numeric id.' };
  }

  const item = indexItems(items).get(id) || null;
  const rows = scheduleRows.filter((r) => String(r.etsy_listing_id) === id);
  const row = rows.sort((a, b) => Number(b.id || 0) - Number(a.id || 0))[0] || null;

  let verdict;
  if (!row) {
    verdict = item
      ? 'not scheduled'
      : 'unknown - no items row either, so the sync has never seen this listing';
  } else if (PENDING.has(String(row.status))) {
    verdict = `already scheduled for ${localTime(row.scheduled_at, timeZone)} `
      + `(${timeZone})`
      + (row.status === 'scheduled' ? ' - already handed to Facebook' : '')
      + (row.status === 'posting' ? ' - being published right now' : '');
  } else if (row.status === 'posted') {
    verdict = `posted on ${localTime(row.posted_at || row.scheduled_at, timeZone)}`;
  } else if (row.status === 'failed') {
    verdict = `failed after ${row.attempts || 0} attempt(s): ${row.error || 'no error recorded'}`;
  } else if (row.status === 'skipped') {
    verdict = 'skipped - its boards were disabled';
  } else {
    verdict = `unknown status "${row.status}"`;
  }

  return {
    ok: true,
    etsy_listing_id: id,
    etsy_url: item ? item.etsy_url : `https://www.etsy.com/listing/${id}`,
    verdict,
    in_items: Boolean(item),
    title: item ? String(item.title || '').slice(0, 120) : '',
    boards: item ? parseList(item.board_slugs) : [],
    image_url: item ? item.image_url || '' : '',
    row: row ? {
      row_id: row.id, status: row.status,
      scheduled_at: row.scheduled_at, scheduled_local: localTime(row.scheduled_at, timeZone),
      posted_at: row.posted_at, attempts: row.attempts, error: row.error,
      fb_post_id: row.fb_post_id,
    } : null,
    can_queue_now: Boolean(item) && !row,
  };
}

/** Board list with what each one is actually contributing. */
function boardsView({ boards = [], items = [], scheduleRows = [] } = {}) {
  const pendingByBoard = {};
  for (const r of scheduleRows) {
    if (!PENDING.has(String(r.status || ''))) continue;
    const b = String(r.board_slug || '');
    pendingByBoard[b] = (pendingByBoard[b] || 0) + 1;
  }
  const itemsByBoard = {};
  for (const it of items) {
    for (const b of parseList(it.board_slugs)) {
      itemsByBoard[b] = (itemsByBoard[b] || 0) + 1;
    }
  }

  return {
    count: boards.length,
    boards: boards
      .slice()
      .sort((a, b) => (Number(b.priority) || 0) - (Number(a.priority) || 0)
        || String(a.board_slug).localeCompare(String(b.board_slug)))
      .map((b) => ({
        board_slug: b.board_slug,
        name: b.name || b.board_slug,
        enabled: b.enabled === true,
        priority: Number(b.priority) || 0,
        rss_url: b.rss_url,
        last_synced_at: b.last_synced_at || null,
        listings: itemsByBoard[b.board_slug] || 0,
        queued_now: pendingByBoard[b.board_slug] || 0,
      })),
  };
}

// ----------------------------------------------------------------- actions

/**
 * Turning a board off must not silently strand its queue, and turning it back
 * on must undo exactly that.
 *
 * Disabling: queued rows whose listing belongs ONLY to disabled boards become
 * skipped. A listing that also sits on an enabled board keeps its slot.
 * Enabling: skipped rows whose listing now has an enabled board go back to
 * queued.
 */
function planCascade({ boards = [], items = [], scheduleRows = [] } = {}) {
  const enabled = new Set(
    boards.filter((b) => b.enabled === true).map((b) => String(b.board_slug))
  );
  const byId = indexItems(items);
  const updates = [];

  for (const r of scheduleRows) {
    const status = String(r.status || '');
    const it = byId.get(String(r.etsy_listing_id));
    if (!it) continue;
    const hasEnabled = parseList(it.board_slugs).some((b) => enabled.has(b));

    if (PENDING.has(status) && !hasEnabled) {
      updates.push({ row_id: r.id, etsy_listing_id: r.etsy_listing_id,
        status: 'skipped',
        error: 'Every board for this listing is disabled.',
        reason: 'board_disabled' });
    } else if (status === 'skipped' && hasEnabled) {
      updates.push({ row_id: r.id, etsy_listing_id: r.etsy_listing_id,
        status: 'queued', error: '', reason: 'board_re_enabled' });
    }
  }

  return {
    updates,
    summary: {
      to_skip: updates.filter((u) => u.reason === 'board_disabled').length,
      to_restore: updates.filter((u) => u.reason === 'board_re_enabled').length,
      enabled_boards: [...enabled],
    },
  };
}

/** Validate an "add board" request into a row ready to insert. */
function planAddBoard({ username = '', board = '', name = '', priority = 0,
                        existing = [] } = {}) {
  const r = resolveBoard(username, board);
  if (!r.ok) return { ok: false, error: r.error };

  if (existing.some((b) => String(b.board_slug) === r.board_slug)) {
    return { ok: false,
      error: `Board "${r.board_slug}" is already in the table. Use the toggle `
        + 'action to enable or disable it.' };
  }

  return {
    ok: true,
    row: {
      board_slug: r.board_slug,
      name: String(name || '').trim() || r.board_slug,
      rss_url: r.rss_url,
      // New boards start disabled on purpose: sync collects their pins, and
      // nothing is published until you turn them on deliberately.
      enabled: false,
      priority: Number(priority) || 0,
      last_synced_at: null,
    },
    note: `Added disabled. Run "A - Sync Boards" to collect its pins, then `
      + 'enable it when you are ready to post from it.',
  };
}

/** Validate a reschedule/remove request against the actual row. */
function planEntryAction({ action = '', rowId = '', newTime = '',
                           scheduleRows = [], timeZone = 'UTC',
                           nowMs = Date.now() } = {}) {
  const id = String(rowId || '').trim();
  const row = scheduleRows.find((r) => String(r.id) === id);
  if (!row) {
    return { ok: false,
      error: `No schedule entry with id ${id || '(empty)'}. The queue view `
        + 'lists the ids.' };
  }

  if (action === 'remove') {
    if (row.status === 'scheduled') {
      return { ok: false,
        error: `Entry ${id} was already handed to Facebook (fb_post_id `
          + `${row.fb_post_id || 'unknown'}). Removing the row here would NOT `
          + 'unpublish it - delete the scheduled post in Meta Business Suite '
          + 'first, then remove the row.' };
    }
    return { ok: true, action: 'remove', row_id: row.id,
      note: `Entry ${id} for listing ${row.etsy_listing_id} will be deleted. `
        + 'The listing becomes eligible for queueing again on the next run of '
        + 'Workflow B.' };
  }

  // reschedule
  const t = Date.parse(newTime);
  if (!Number.isFinite(t)) {
    return { ok: false,
      error: `Could not read "${newTime}" as a time. Use an ISO timestamp `
        + 'like 2026-10-05T14:00:00Z, or 2026-10-05 16:00 for local time.' };
  }
  if (t <= nowMs) {
    return { ok: false,
      error: `${localTime(new Date(t).toISOString(), timeZone)} is in the past.` };
  }
  if (row.status === 'scheduled') {
    return { ok: false,
      error: `Entry ${id} is already scheduled on Facebook. Change the time in `
        + 'Meta Business Suite, or remove it there and reschedule here.' };
  }

  return {
    ok: true,
    action: 'reschedule',
    row_id: row.id,
    scheduled_at: new Date(t).toISOString(),
    // A failed row being rescheduled is a fresh start, so clear the failure.
    status: 'queued',
    note: `Entry ${id} moved to ${localTime(new Date(t).toISOString(), timeZone)} `
      + `(${timeZone}) and reset to queued.`,
  };
}

// ---------------------------------------------------------------- n8n glue
// After a board is toggled, decide which queue rows must follow.
//
// $('Load Boards') still holds the state from BEFORE the update, so the
// toggle is applied in memory first - otherwise the cascade would be computed
// against stale data.
// Mode: Run Once for All Items.

const req = $('Parse Request').first().json;
const items = $('Load Items').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);
const scheduleRows = $('Load Schedule').all().map((i) => i.json || {})
  .filter((r) => r.etsy_listing_id);

const boards = $('Load Boards').all().map((i) => ({ ...(i.json || {}) }))
  .filter((b) => b.board_slug)
  .map((b) => String(b.board_slug) === String(req.board_slug)
    ? { ...b, enabled: req.enabled } : b);

const plan = planCascade({ boards, items, scheduleRows });

if (!plan.updates.length) {
  return [{ json: { _kind: 'cascade_none', ...plan.summary,
    board_slug: req.board_slug, enabled: req.enabled } }];
}

return plan.updates.map((u) => ({ json: {
  _kind: 'cascade', ...u,
  board_slug: req.board_slug, enabled: req.enabled,
} }));

// Renders the outcome of a board toggle, including what the cascade did.
// Mode: Run Once for All Items.

const req = $('Parse Request').first().json;

let skipped = 0;
let restored = 0;
try {
  for (const i of $('Cascade Plan').all()) {
    const j = i.json || {};
    if (j._kind !== 'cascade') continue;
    if (j.status === 'skipped') skipped++;
    if (j.status === 'queued') restored++;
  }
} catch { /* cascade produced nothing */ }

const state = req.enabled ? 'ENABLED' : 'DISABLED';
const lines = [`Board "${req.board_slug}" is now ${state}.`, ''];

if (req.enabled) {
  lines.push(restored
    ? `${restored} previously skipped entr${restored === 1 ? 'y was' : 'ies were'} `
      + 'put back in the queue.'
    : 'No skipped entries needed restoring.');
  lines.push('', 'Its listings can now be published. The next run of '
    + '"B - Build Schedule" will queue any that are not scheduled yet.');
} else {
  lines.push(skipped
    ? `${skipped} queued entr${skipped === 1 ? 'y was' : 'ies were'} moved to `
      + 'skipped, because their listings belong only to disabled boards.'
    : 'No queued entries were affected - their listings also sit on boards '
      + 'that are still enabled.');
  lines.push('', 'Pins keep being collected for this board; nothing new will '
    + 'be published from it. Enabling it again restores exactly the entries '
    + 'that were skipped.');
}

return [{ json: { title: `Board ${req.board_slug}: ${state}`, text: lines.join('\n') } }];

// Renders the outcome of an add-board / reschedule / remove action.
// Mode: Run Once for All Items.

const req = $('Parse Request').first().json;

if (req._kind === 'addboard') {
  return [{ json: {
    title: `Board "${req.board_slug}" added`,
    text: [
      `slug     ${req.board_slug}`,
      `name     ${req.name}`,
      `priority ${req.priority}`,
      `feed     ${req.rss_url}`,
      `enabled  false`,
      '',
      req.note,
    ].join('\n'),
  } }];
}

if (req._kind === 'reschedule') {
  return [{ json: {
    title: `Entry #${req.row_id} rescheduled`,
    text: `${req.note}\n\nIt will be picked up by "C - Publisher" when its new `
      + 'slot comes round.',
  } }];
}

if (req._kind === 'remove') {
  return [{ json: {
    title: `Entry #${req.row_id} removed`,
    text: req.note,
  } }];
}

return [{ json: { title: 'Done', text: JSON.stringify(req, null, 2) } }];

// Capability probe. Answers two questions for Workflow A:
//   1. is $helpers.httpRequest available inside a Code node?
//   2. does the /originals/ image upgrade actually resolve for a real pin?
const out = {
  helpers_available: typeof $helpers !== 'undefined' && !!($helpers && $helpers.httpRequest),
  node_version: typeof process !== 'undefined' ? process.version : 'n/a',
};
if (!out.helpers_available) { out.note = 'Fall back to HTTP Request nodes for image verification.'; return [{ json: out }]; }

const base = 'https://i.pinimg.com';
const p = '/ef/dc/0f/efdc0f00cd8e58ed53e28e44583b7269';
const candidates = [
  base + '/originals' + p + '.jpg',
  base + '/originals' + p + '.png',
  base + '/1200x' + p + '.jpg',
  base + '/736x' + p + '.jpg',
  base + '/236x' + p + '.jpg',
];

out.results = [];
for (const url of candidates) {
  try {
    const res = await $helpers.httpRequest({
      method: 'HEAD', url, returnFullResponse: true, timeout: 15000,
      headers: { 'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/125.0.0.0 Safari/537.36' },
    });
    const h = res.headers || {};
    out.results.push({ url, status: res.statusCode, bytes: Number(h['content-length'] || 0) || null, type: h['content-type'] || null });
    if (res.statusCode === 200 && !out.chosen) { out.chosen = url; out.chosen_bytes = Number(h['content-length'] || 0) || null; }
  } catch (e) {
    out.results.push({ url, error: String(e.message || e).slice(0, 160) });
  }
}
out.verdict = out.chosen ? 'image upgrade works; HEAD verification usable in a Code node'
                         : 'no candidate returned 200 - check headers or fall back';
return [{ json: out }];

// Flattens the config table into one object so later nodes can read settings
// as $('Config').first().json.SLOTS instead of searching rows.
// Defaults are applied for any key missing from the table, so the workflow
// still runs on a fresh install. Mode: Run Once for All Items.

const DEFAULTS = {
  TIMEZONE: 'Europe/Belgrade',
  SLOTS: '10:00,15:00,20:00',
  TEXT_MODE: 'pinterest',
  REPOST_AFTER_DAYS: '60',
  SCHEDULE_HORIZON_DAYS: '14',
  MAX_QUEUE_PER_RUN: '60',
  RETRY_DELAY_MINUTES: '30',
  EXTRA_HASHTAGS: '',
  POST_TEXT_MAX_CHARS: '600',
  FB_PAGE_ID: '',
  PIN_RESOLVE_MAX_PER_RUN: '10',
  RESOLVE_THROTTLE_MS: '2000',
  RESOLVE_MAX_ATTEMPTS: '3',
  DRY_RUN: 'true',
  MAX_PUBLISH_PER_RUN: '20',
  FB_API_VERSION: 'v21.0',
  AUTH_MODE: 'oauth',
};

const cfg = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key) cfg[String(r.key)] = r.value == null ? '' : String(r.value);
}

// Typed views, so consumers never re-parse strings.
cfg._slots = String(cfg.SLOTS).split(',').map((s) => s.trim()).filter(Boolean);
cfg._repost_after_days = Number(cfg.REPOST_AFTER_DAYS) || 0;
cfg._resolve_max = Math.max(1, Number(cfg.PIN_RESOLVE_MAX_PER_RUN) || 10);
cfg._throttle_ms = Math.max(0, Number(cfg.RESOLVE_THROTTLE_MS) || 0);
cfg._resolve_max_attempts = Math.max(1, Number(cfg.RESOLVE_MAX_ATTEMPTS) || 3);
cfg._horizon_days = Math.max(1, Number(cfg.SCHEDULE_HORIZON_DAYS) || 14);
cfg._max_queue = Math.max(1, Number(cfg.MAX_QUEUE_PER_RUN) || 60);
cfg._text_max = Math.max(80, Number(cfg.POST_TEXT_MAX_CHARS) || 600);
cfg._retry_delay_minutes = Math.max(1, Number(cfg.RETRY_DELAY_MINUTES) || 30);
cfg._max_publish = Math.max(1, Number(cfg.MAX_PUBLISH_PER_RUN) || 20);
// Anything but an explicit "false" keeps the safety on.
cfg._dry_run = String(cfg.DRY_RUN).trim().toLowerCase() !== 'false';
// Anything other than an explicit "token" means the OAuth login path.
cfg._auth_mode = String(cfg.AUTH_MODE).trim().toLowerCase() === 'token'
  ? 'token' : 'oauth';

return [{ json: cfg }];

// Resolves the Page and its access token at run time.
//
// The OAuth credential holds a USER token (that is what the login dialog
// grants). Posting to a Page needs a PAGE token, which /me/accounts derives
// from it. Doing that on every run means:
//   - no token is ever copied by hand or stored in the config table
//   - a Page token derived from a long-lived user token does not expire
//   - FB_PAGE_ID becomes optional when the account manages one Page
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const mode = cfg._auth_mode; // 'oauth' | 'token'

// The remedy differs per mode, so hints name the thing the user actually has.
const reconnect = mode === 'oauth'
  ? 'Open Credentials -> "Facebook OAuth (login)", fill in App ID and App '
    + 'Secret, then click "Connect my account" and approve the Facebook window.'
  : 'Open Credentials -> "Facebook User Token" and paste a valid long-lived '
    + 'USER token (Graph API Explorer gives you one; see '
    + 'docs/facebook-page-token.md).';
const res = $input.first().json || {};
const body = res.body && typeof res.body === 'object' ? res.body : res;
const httpStatus = res.statusCode ?? null;

// Two different failures arrive here and must not be conflated:
//
//  1. n8n could not even send the request - almost always because the OAuth
//     credential has never been connected. The node then emits { error: ... }
//     with no statusCode, and the error object often serializes to {}.
//  2. Facebook answered with a Graph error, which has type/code/message.
const hasGraphError = body && body.error
  && (body.error.message || body.error.type || body.error.code !== undefined);

if (httpStatus == null && !hasGraphError) {
  const raw = res.error ?? body?.error;
  const detail = raw && (raw.message || raw.description || raw.reason);
  return [{ json: {
    ok: false,
    stage: 'request_not_sent',
    error: 'The call to /me/accounts never reached Facebook'
      + (detail ? `: ${detail}` : '.'),
    hint: `AUTH_MODE is "${mode}", and its credential is not usable yet. `
        + reconnect + ' Re-run afterwards.',
    http_status: null,
  } }];
}

if (hasGraphError) {
  const e = body.error;
  const parts = [e.type || 'GraphError', e.code !== undefined ? `(${e.code})` : '']
    .filter(Boolean).join(' ');
  return [{ json: {
    ok: false,
    stage: 'me_accounts_failed',
    error: `${parts}: ${e.message || 'no message returned'}`
      + (e.error_user_msg ? ` - ${e.error_user_msg}` : ''),
    hint: e.code === 190
      ? 'The token has expired or been revoked. ' + reconnect
      : 'Check that pages_show_list, pages_manage_posts and '
        + 'pages_read_engagement were all granted. '
        + (mode === 'token'
          ? 'Note: this must be a USER token, not a Page token - /me/accounts '
            + 'is what turns one into the other.'
          : ''),
    http_status: httpStatus,
  } }];
}

const pages = Array.isArray(body && body.data) ? body.data : [];

if (!pages.length) {
  return [{ json: {
    ok: false,
    stage: 'no_pages',
    error: 'The logged-in account manages no Pages that this app can see.',
    hint: 'You must be an admin of the Page, and the login must have granted '
        + 'pages_show_list.',
    http_status: httpStatus,
  } }];
}

const wanted = String(cfg.FB_PAGE_ID || '').trim();
let page = null;

if (wanted) {
  page = pages.find((p) => String(p.id) === wanted) || null;
  if (!page) {
    return [{ json: {
      ok: false,
      stage: 'page_id_not_found',
      error: `FB_PAGE_ID is ${wanted}, but the logged-in account does not `
        + 'manage a Page with that id.',
      pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
      hint: 'Fix FB_PAGE_ID in the config table, or clear it if the account '
          + 'manages exactly one Page.',
      http_status: httpStatus,
    } }];
  }
} else if (pages.length === 1) {
  page = pages[0];
} else {
  return [{ json: {
    ok: false,
    stage: 'page_id_required',
    error: `The account manages ${pages.length} Pages, so FB_PAGE_ID must say `
      + 'which one to post to.',
    pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
    http_status: httpStatus,
  } }];
}

if (!page.access_token) {
  return [{ json: {
    ok: false,
    stage: 'no_page_token',
    error: `Page ${page.id} came back without an access_token.`,
    hint: 'The login did not grant pages_manage_posts for this Page.',
  } }];
}

return [{ json: {
  ok: true,
  page_id: String(page.id),
  page_name: String(page.name || ''),
  // Used as a request header by the publish nodes. Never written to a table.
  page_token: String(page.access_token),
  page_id_source: wanted ? 'config' : 'only_page_on_account',
  auth_mode: mode,
  pages_available: pages.length,
} }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Boards').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Items').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

/**
 * Publish selection. Pure functions, no n8n, no clock of its own.
 *
 * Two publishing shapes, chosen per row rather than globally:
 *
 *   scheduled - hand the post to Facebook with published=false and a
 *               scheduled_publish_time, and let Facebook publish it. Fewer
 *               moving parts: n8n does not have to be alive at 10:00.
 *   immediate - publish now. Used when a row's slot has already arrived (or
 *               passed), because Facebook refuses a scheduled time that is
 *               not at least 10 minutes out.
 *
 * Source-agnostic: works from schedule rows and items keyed on
 * etsy_listing_id.
 */

const MIN_LEAD_MS = 10 * 60_000;            // Facebook's own minimum
const MAX_AHEAD_MS = 180 * 86_400_000;      // Facebook's own maximum (~6 months)

/** Statuses this workflow is allowed to act on. */
const ACTIONABLE = new Set(['queued', 'failed']);

function parseList(v) {
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === 'string' && v.trim()) {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p.map(String);
      if (typeof p === 'string') return [p];
    } catch { return [v]; }
  }
  return [];
}

/**
 * Decide what to publish this run.
 *
 * @returns {{toPublish:Array, toSkip:Array, notYet:Array, report:Object}}
 */
function selectForPublish({
  rows = [],
  items = [],
  enabledBoards = [],
  nowMs = Date.now(),
  retryDelayMinutes = 30,
  maxAttempts = 2,
  maxPerRun = 20,
  minLeadMs = MIN_LEAD_MS,
  maxAheadMs = MAX_AHEAD_MS,
} = {}) {
  const enabled = new Set(enabledBoards.map(String));
  const itemById = new Map();
  for (const it of items) {
    if (it && it.etsy_listing_id) itemById.set(String(it.etsy_listing_id), it);
  }

  const toPublish = [];
  const toSkip = [];
  const notYet = [];

  // Earliest slots first: a backlog drains in schedule order.
  const ordered = rows
    .filter((r) => r && ACTIONABLE.has(String(r.status || '')))
    .slice()
    .sort((a, b) => String(a.scheduled_at || '').localeCompare(String(b.scheduled_at || '')));

  for (const row of ordered) {
    const id = String(row.etsy_listing_id || '');
    const status = String(row.status || '');
    const attempts = Number(row.attempts) || 0;

    // --- retry gating for a row that already failed ------------------------
    if (status === 'failed') {
      if (attempts >= maxAttempts) {
        notYet.push({ row_id: row.id, etsy_listing_id: id,
          reason: 'retry_limit_reached', attempts, error: row.error || '' });
        continue;
      }
      const last = Date.parse(row.last_attempt_at || row.updatedAt || '');
      const waited = Number.isFinite(last) ? nowMs - last : Infinity;
      if (waited < retryDelayMinutes * 60_000) {
        notYet.push({ row_id: row.id, etsy_listing_id: id,
          reason: 'retry_delay_not_elapsed', attempts,
          minutes_remaining: Math.ceil((retryDelayMinutes * 60_000 - waited) / 60_000) });
        continue;
      }
    }

    // --- the item must still exist ----------------------------------------
    const item = itemById.get(id);
    if (!item) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'item_row_missing',
        error: `No items row for listing ${id}. It was removed, or the sync `
          + 'never produced it.' });
      continue;
    }

    // --- boards must still be enabled -------------------------------------
    const boards = parseList(item.board_slugs);
    if (!boards.some((b) => enabled.has(b))) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'skipped',
        reason: 'all_boards_disabled',
        error: `Every board for this listing is disabled (${boards.join(', ') || 'none'}).` });
      continue;
    }

    // --- there must be something to post ----------------------------------
    const image_url = String(item.image_url || '');
    if (!image_url) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'no_image', error: 'The items row has no image_url.' });
      continue;
    }
    const post_text = String(row.post_text || '');
    if (!post_text.trim()) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'no_post_text', error: 'The schedule row has an empty post_text.' });
      continue;
    }

    // --- immediate or scheduled? ------------------------------------------
    const slot = Date.parse(row.scheduled_at || '');
    if (!Number.isFinite(slot)) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'bad_scheduled_at',
        error: `scheduled_at is not a date: ${row.scheduled_at}` });
      continue;
    }

    const lead = slot - nowMs;
    if (lead > maxAheadMs) {
      // Beyond what Facebook will accept; a later run will pick it up.
      notYet.push({ row_id: row.id, etsy_listing_id: id,
        reason: 'beyond_facebook_scheduling_window',
        scheduled_at: row.scheduled_at,
        days_ahead: Math.round(lead / 86_400_000) });
      continue;
    }

    const mode = lead >= minLeadMs ? 'scheduled' : 'immediate';

    if (toPublish.length >= maxPerRun) {
      notYet.push({ row_id: row.id, etsy_listing_id: id,
        reason: 'max_publish_per_run', scheduled_at: row.scheduled_at });
      continue;
    }

    toPublish.push({
      row_id: row.id,
      etsy_listing_id: id,
      board_slug: row.board_slug || '',
      post_text,
      image_url,
      etsy_url: item.etsy_url || `https://www.etsy.com/listing/${id}`,
      scheduled_at: row.scheduled_at,
      mode,
      // Facebook wants whole seconds since the epoch, and only for a
      // scheduled post.
      scheduled_publish_time: mode === 'scheduled' ? Math.floor(slot / 1000) : null,
      attempts: attempts + 1,
      was_retry: status === 'failed',
    });
  }

  return {
    toPublish,
    toSkip,
    notYet,
    report: {
      actionable_rows: ordered.length,
      publishing: toPublish.length,
      scheduled: toPublish.filter((p) => p.mode === 'scheduled').length,
      immediate: toPublish.filter((p) => p.mode === 'immediate').length,
      retries: toPublish.filter((p) => p.was_retry).length,
      skipping: toSkip.length,
      deferred: notYet.length,
      skip_reasons: toSkip.reduce((a, s) => {
        a[s.reason] = (a[s.reason] || 0) + 1; return a;
      }, {}),
      defer_reasons: notYet.reduce((a, s) => {
        a[s.reason] = (a[s.reason] || 0) + 1; return a;
      }, {}),
    },
  };
}

/**
 * Turn a selection entry into the two Graph API calls.
 *
 * A scheduled photo post is a two-step operation: upload the photo
 * unpublished to get a media id, then create the feed post with that
 * attachment and the publish time. Posting the photo directly to /photos with
 * a scheduled time is not reliable across API versions.
 */
function buildGraphCalls(entry, { pageId, apiVersion = 'v21.0' } = {}) {
  if (!pageId) throw new Error('FB_PAGE_ID is not set in the config table.');
  const base = `https://graph.facebook.com/${apiVersion}`;
  return {
    photo: {
      url: `${base}/${pageId}/photos`,
      body: { url: entry.image_url, published: false },
    },
    // media_fbid is filled in once the upload returns.
    feed: {
      url: `${base}/${pageId}/feed`,
      body: {
        message: entry.post_text,
        published: entry.mode === 'scheduled' ? false : true,
        ...(entry.mode === 'scheduled'
          ? { scheduled_publish_time: entry.scheduled_publish_time } : {}),
      },
    },
  };
}

// ---------------------------------------------------------------- n8n glue
// Workflow C: decide what to publish, and how.
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const boards = $('Load Boards').all().map((i) => i.json || {}).filter((b) => b.board_slug);
const items = $('Load Items').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);
const rows = $('Load Queue').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);

const enabledBoards = boards.filter((b) => b.enabled === true).map((b) => b.board_slug);
const nowMs = Date.now();

const plan = selectForPublish({
  rows,
  items,
  enabledBoards,
  nowMs,
  retryDelayMinutes: cfg._retry_delay_minutes,
  maxAttempts: 2,
  maxPerRun: cfg._max_publish,
});

// In live mode the Page id comes from the OAuth login itself, so the config
// key is optional. Pick Page does not run during a dry run.
const oauthPageId = (() => {
  try {
    const p = $('Pick Page').first().json;
    return p && p.ok ? String(p.page_id) : '';
  } catch {
    return '';
  }
})();

const realPageId = String(cfg.FB_PAGE_ID || '').trim() || oauthPageId;
const apiVersion = String(cfg.FB_API_VERSION || 'v21.0').trim();
const out = [];

// A dry run never calls Facebook, so it does not need a real Page id - and
// being able to validate the whole path BEFORE obtaining a token is the
// entire point of the dry run. The placeholder is obvious on sight in the
// logged URLs.
const pageId = realPageId || (cfg._dry_run ? 'FB_PAGE_ID_NOT_SET' : '');

// Outside a dry run, a missing Page id means nothing can be published. Say so
// once, rather than failing every row with an opaque HTTP error.
if (plan.toPublish.length && !pageId) {
  out.push({ json: {
    _kind: 'report',
    workflow: 'C - Publisher',
    level: 'error',
    context: 'publish_blocked',
    created_at: new Date(nowMs).toISOString(),
    ...plan.report,
    publishing: 0,
    note: 'FB_PAGE_ID is empty in the config table, so nothing was published. '
        + `${plan.toPublish.length} row(s) are ready and waiting. Either `
        + 'connect the "Facebook OAuth (login)" credential, which supplies '
        + 'the Page id automatically, or fill FB_PAGE_ID in the config table.',
  } });
  // Skip rows still get applied - a disabled board should not wait on a token.
  for (const s of plan.toSkip) out.push({ json: { _kind: 'skip', ...s } });
  return out;
}

for (const p of plan.toPublish) {
  const calls = buildGraphCalls(p, { pageId, apiVersion });
  out.push({ json: {
    _kind: 'publish',
    ...p,
    fb_photo_url: calls.photo.url,
    fb_feed_url: calls.feed.url,
    fb_published: calls.feed.body.published,
    fb_scheduled_publish_time: calls.feed.body.scheduled_publish_time ?? null,
    dry_run: cfg._dry_run,
  } });
}

for (const s of plan.toSkip) out.push({ json: { _kind: 'skip', ...s } });

out.push({ json: {
  _kind: 'report',
  workflow: 'C - Publisher',
  level: plan.toSkip.length ? 'warn' : 'info',
  context: 'publish_summary',
  created_at: new Date(nowMs).toISOString(),
  dry_run: cfg._dry_run,
  page_id_set: Boolean(realPageId),
  ...plan.report,
  deferred_examples: plan.notYet.slice(0, 5),
  note: cfg._dry_run
    ? 'DRY_RUN is on: nothing was sent to Facebook. The exact request bodies '
      + 'are in errors_log. Set DRY_RUN=false in config once the token is in.'
      + (realPageId ? '' : ' FB_PAGE_ID is still empty, so the logged URLs '
        + 'carry a placeholder.')
    : `Publishing ${plan.report.publishing} post(s): `
      + `${plan.report.scheduled} handed to Facebook as scheduled, `
      + `${plan.report.immediate} published immediately.`,
} });

return out;

// Confirms the atomic claim actually took.
//
// "Claim Row" updates the row only when its status is still the one we read,
// so if another run (or a second trigger firing) got there first, zero rows
// change. That is the double-post guard: without a confirmed claim we do not
// call Facebook at all.
// Mode: Run Once for All Items.

const entry = $('Loop Publish').first().json;
const updated = $input.all().map((i) => i.json || {}).filter((r) => r && r.id);

const claimed = updated.length > 0;

return [{ json: {
  ...entry,
  claimed,
  claim_note: claimed
    ? `Row ${entry.row_id} claimed (status -> posting).`
    : `Row ${entry.row_id} was NOT claimed - its status changed since it was `
      + 'read, so another run owns it. Skipping to avoid a double post.',
} }];

// Reads the photo id from whichever upload path ran.
//
// The URL upload is tried first. If Facebook cannot fetch the image itself
// (Pinterest hotlink protection, for example) the binary path downloads the
// bytes in n8n and uploads them as a file instead.
// Mode: Run Once for All Items.

const entry = $('Verify Claim').first().json;

const idFrom = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    // Graph returns { id } for an unpublished photo. With fullResponse the
    // payload sits under .body.
    const body = j.body && typeof j.body === 'object' ? j.body : j;
    return body && body.id ? String(body.id) : '';
  } catch {
    return ''; // node did not run
  }
};

const viaUrl = idFrom('FB Upload Photo By URL');
const viaBinary = idFrom('FB Upload Photo Binary');
const media_fbid = viaUrl || viaBinary;

if (!media_fbid) {
  return [{ json: { ...entry, media_fbid: '', upload_path: 'none',
    upload_error: 'Neither the URL upload nor the binary upload returned a '
      + 'photo id. See the two FB Upload nodes in this execution.' } }];
}

return [{ json: {
  ...entry,
  media_fbid,
  upload_path: viaUrl ? 'url' : 'binary',
  upload_error: '',
} }];

// Maps the Graph API response onto the schedule row update.
// Mode: Run Once for All Items.

const entry = $('Media Id').first().json;
const nowIso = new Date().toISOString();

const res = $input.first().json || {};
const body = res.body && typeof res.body === 'object' ? res.body : res;
const httpStatus = res.statusCode ?? null;

// Graph returns { id: "<page>_<post>" } on success, or { error: {...} }.
const postId = body && body.id ? String(body.id) : '';
const gErr = body && body.error ? body.error : null;

if (postId && !gErr) {
  const scheduled = entry.mode === 'scheduled';
  return [{ json: {
    row_id: entry.row_id,
    etsy_listing_id: entry.etsy_listing_id,
    // `scheduled` means Facebook accepted it and will publish at
    // scheduled_at. It is deliberately distinct from `posted` so the
    // scheduler still treats the listing as taken, and so a later
    // verification pass can tell the two apart.
    status: scheduled ? 'scheduled' : 'posted',
    fb_post_id: postId,
    fb_media_id: entry.media_fbid || '',
    error: '',
    attempts: entry.attempts,
    last_attempt_at: nowIso,
    posted_at: scheduled ? entry.scheduled_at : nowIso,
    _ok: true,
    _note: scheduled
      ? `Accepted by Facebook, will publish at ${entry.scheduled_at}.`
      : 'Published immediately.',
  } }];
}

const message = gErr
  ? `${gErr.type || 'GraphError'} ${gErr.code ?? ''}: ${gErr.message || ''}`
    + (gErr.error_user_msg ? ` (${gErr.error_user_msg})` : '')
  : entry.upload_error
    || `Facebook returned no post id (http ${httpStatus ?? 'n/a'}).`;

return [{ json: {
  row_id: entry.row_id,
  etsy_listing_id: entry.etsy_listing_id,
  status: 'failed',
  fb_post_id: '',
  fb_media_id: entry.media_fbid || '',
  error: String(message).slice(0, 500),
  attempts: entry.attempts,
  last_attempt_at: nowIso,
  posted_at: null,
  _ok: false,
  _note: entry.attempts >= 2
    ? 'Second failure - the row is parked as failed and will not be retried '
      + 'automatically. Reschedule it from Workflow D once the cause is fixed.'
    : `First failure - it will be retried after the configured delay.`,
} }];

// Final report for a publish run. Tolerates branches that did not execute.
// Mode: Run Once for All Items.

const safe = (name) => {
  try { return $(name).all().map((i) => i.json || {}); } catch { return []; }
};

const results = safe('Handle Result');
const ok = results.filter((r) => r._ok);
const failed = results.filter((r) => r._ok === false);
const dry = safe('Log Dry Run');

return [{ json: {
  workflow: 'C - Publisher',
  level: failed.length ? 'error' : 'info',
  context: 'publish_run',
  created_at: new Date().toISOString(),
  published_ok: ok.length,
  scheduled_on_facebook: ok.filter((r) => r.status === 'scheduled').length,
  published_immediately: ok.filter((r) => r.status === 'posted').length,
  failed: failed.length,
  dry_run_entries: dry.length,
  failures: failed.map((f) => ({
    etsy_listing_id: f.etsy_listing_id, attempts: f.attempts, error: f.error,
  })),
  successes: ok.map((r) => ({
    etsy_listing_id: r.etsy_listing_id, status: r.status,
    fb_post_id: r.fb_post_id, posted_at: r.posted_at,
  })),
} }];

// Flattens the config table into one object so later nodes can read settings
// as $('Config').first().json.SLOTS instead of searching rows.
// Defaults are applied for any key missing from the table, so the workflow
// still runs on a fresh install. Mode: Run Once for All Items.

const DEFAULTS = {
  TIMEZONE: 'Europe/Belgrade',
  SLOTS: '10:00,15:00,20:00',
  TEXT_MODE: 'pinterest',
  REPOST_AFTER_DAYS: '60',
  SCHEDULE_HORIZON_DAYS: '14',
  MAX_QUEUE_PER_RUN: '60',
  RETRY_DELAY_MINUTES: '30',
  EXTRA_HASHTAGS: '',
  POST_TEXT_MAX_CHARS: '600',
  FB_PAGE_ID: '',
  PIN_RESOLVE_MAX_PER_RUN: '10',
  RESOLVE_THROTTLE_MS: '2000',
  RESOLVE_MAX_ATTEMPTS: '3',
  DRY_RUN: 'true',
  MAX_PUBLISH_PER_RUN: '20',
  FB_API_VERSION: 'v21.0',
  AUTH_MODE: 'oauth',
};

const cfg = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key) cfg[String(r.key)] = r.value == null ? '' : String(r.value);
}

// Typed views, so consumers never re-parse strings.
cfg._slots = String(cfg.SLOTS).split(',').map((s) => s.trim()).filter(Boolean);
cfg._repost_after_days = Number(cfg.REPOST_AFTER_DAYS) || 0;
cfg._resolve_max = Math.max(1, Number(cfg.PIN_RESOLVE_MAX_PER_RUN) || 10);
cfg._throttle_ms = Math.max(0, Number(cfg.RESOLVE_THROTTLE_MS) || 0);
cfg._resolve_max_attempts = Math.max(1, Number(cfg.RESOLVE_MAX_ATTEMPTS) || 3);
cfg._horizon_days = Math.max(1, Number(cfg.SCHEDULE_HORIZON_DAYS) || 14);
cfg._max_queue = Math.max(1, Number(cfg.MAX_QUEUE_PER_RUN) || 60);
cfg._text_max = Math.max(80, Number(cfg.POST_TEXT_MAX_CHARS) || 600);
cfg._retry_delay_minutes = Math.max(1, Number(cfg.RETRY_DELAY_MINUTES) || 30);
cfg._max_publish = Math.max(1, Number(cfg.MAX_PUBLISH_PER_RUN) || 20);
// Anything but an explicit "false" keeps the safety on.
cfg._dry_run = String(cfg.DRY_RUN).trim().toLowerCase() !== 'false';
// Anything other than an explicit "token" means the OAuth login path.
cfg._auth_mode = String(cfg.AUTH_MODE).trim().toLowerCase() === 'token'
  ? 'token' : 'oauth';

return [{ json: cfg }];

// Resolves the Page and its access token at run time.
//
// The OAuth credential holds a USER token (that is what the login dialog
// grants). Posting to a Page needs a PAGE token, which /me/accounts derives
// from it. Doing that on every run means:
//   - no token is ever copied by hand or stored in the config table
//   - a Page token derived from a long-lived user token does not expire
//   - FB_PAGE_ID becomes optional when the account manages one Page
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const mode = cfg._auth_mode; // 'oauth' | 'token'

// The remedy differs per mode, so hints name the thing the user actually has.
const reconnect = mode === 'oauth'
  ? 'Open Credentials -> "Facebook OAuth (login)", fill in App ID and App '
    + 'Secret, then click "Connect my account" and approve the Facebook window.'
  : 'Open Credentials -> "Facebook User Token" and paste a valid long-lived '
    + 'USER token (Graph API Explorer gives you one; see '
    + 'docs/facebook-page-token.md).';
const res = $input.first().json || {};
const body = res.body && typeof res.body === 'object' ? res.body : res;
const httpStatus = res.statusCode ?? null;

// Two different failures arrive here and must not be conflated:
//
//  1. n8n could not even send the request - almost always because the OAuth
//     credential has never been connected. The node then emits { error: ... }
//     with no statusCode, and the error object often serializes to {}.
//  2. Facebook answered with a Graph error, which has type/code/message.
const hasGraphError = body && body.error
  && (body.error.message || body.error.type || body.error.code !== undefined);

if (httpStatus == null && !hasGraphError) {
  const raw = res.error ?? body?.error;
  const detail = raw && (raw.message || raw.description || raw.reason);
  return [{ json: {
    ok: false,
    stage: 'request_not_sent',
    error: 'The call to /me/accounts never reached Facebook'
      + (detail ? `: ${detail}` : '.'),
    hint: `AUTH_MODE is "${mode}", and its credential is not usable yet. `
        + reconnect + ' Re-run afterwards.',
    http_status: null,
  } }];
}

if (hasGraphError) {
  const e = body.error;
  const parts = [e.type || 'GraphError', e.code !== undefined ? `(${e.code})` : '']
    .filter(Boolean).join(' ');
  return [{ json: {
    ok: false,
    stage: 'me_accounts_failed',
    error: `${parts}: ${e.message || 'no message returned'}`
      + (e.error_user_msg ? ` - ${e.error_user_msg}` : ''),
    hint: e.code === 190
      ? 'The token has expired or been revoked. ' + reconnect
      : 'Check that pages_show_list, pages_manage_posts and '
        + 'pages_read_engagement were all granted. '
        + (mode === 'token'
          ? 'Note: this must be a USER token, not a Page token - /me/accounts '
            + 'is what turns one into the other.'
          : ''),
    http_status: httpStatus,
  } }];
}

const pages = Array.isArray(body && body.data) ? body.data : [];

if (!pages.length) {
  return [{ json: {
    ok: false,
    stage: 'no_pages',
    error: 'The logged-in account manages no Pages that this app can see.',
    hint: 'You must be an admin of the Page, and the login must have granted '
        + 'pages_show_list.',
    http_status: httpStatus,
  } }];
}

const wanted = String(cfg.FB_PAGE_ID || '').trim();
let page = null;

if (wanted) {
  page = pages.find((p) => String(p.id) === wanted) || null;
  if (!page) {
    return [{ json: {
      ok: false,
      stage: 'page_id_not_found',
      error: `FB_PAGE_ID is ${wanted}, but the logged-in account does not `
        + 'manage a Page with that id.',
      pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
      hint: 'Fix FB_PAGE_ID in the config table, or clear it if the account '
          + 'manages exactly one Page.',
      http_status: httpStatus,
    } }];
  }
} else if (pages.length === 1) {
  page = pages[0];
} else {
  return [{ json: {
    ok: false,
    stage: 'page_id_required',
    error: `The account manages ${pages.length} Pages, so FB_PAGE_ID must say `
      + 'which one to post to.',
    pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
    http_status: httpStatus,
  } }];
}

if (!page.access_token) {
  return [{ json: {
    ok: false,
    stage: 'no_page_token',
    error: `Page ${page.id} came back without an access_token.`,
    hint: 'The login did not grant pages_manage_posts for this Page.',
  } }];
}

return [{ json: {
  ok: true,
  page_id: String(page.id),
  page_name: String(page.name || ''),
  // Used as a request header by the publish nodes. Never written to a table.
  page_token: String(page.access_token),
  page_id_source: wanted ? 'config' : 'only_page_on_account',
  auth_mode: mode,
  pages_available: pages.length,
} }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Boards').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

// Collapses the branch to ONE item so the next data-table read runs
// once. Rows stay reachable via $('Load Items').all().
// Mode: Run Once for All Items.

return [{ json: { loaded: $input.all().length } }];

/**
 * Publish selection. Pure functions, no n8n, no clock of its own.
 *
 * Two publishing shapes, chosen per row rather than globally:
 *
 *   scheduled - hand the post to Facebook with published=false and a
 *               scheduled_publish_time, and let Facebook publish it. Fewer
 *               moving parts: n8n does not have to be alive at 10:00.
 *   immediate - publish now. Used when a row's slot has already arrived (or
 *               passed), because Facebook refuses a scheduled time that is
 *               not at least 10 minutes out.
 *
 * Source-agnostic: works from schedule rows and items keyed on
 * etsy_listing_id.
 */

const MIN_LEAD_MS = 10 * 60_000;            // Facebook's own minimum
const MAX_AHEAD_MS = 180 * 86_400_000;      // Facebook's own maximum (~6 months)

/** Statuses this workflow is allowed to act on. */
const ACTIONABLE = new Set(['queued', 'failed']);

function parseList(v) {
  if (Array.isArray(v)) return v.map(String);
  if (typeof v === 'string' && v.trim()) {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p.map(String);
      if (typeof p === 'string') return [p];
    } catch { return [v]; }
  }
  return [];
}

/**
 * Decide what to publish this run.
 *
 * @returns {{toPublish:Array, toSkip:Array, notYet:Array, report:Object}}
 */
function selectForPublish({
  rows = [],
  items = [],
  enabledBoards = [],
  nowMs = Date.now(),
  retryDelayMinutes = 30,
  maxAttempts = 2,
  maxPerRun = 20,
  minLeadMs = MIN_LEAD_MS,
  maxAheadMs = MAX_AHEAD_MS,
} = {}) {
  const enabled = new Set(enabledBoards.map(String));
  const itemById = new Map();
  for (const it of items) {
    if (it && it.etsy_listing_id) itemById.set(String(it.etsy_listing_id), it);
  }

  const toPublish = [];
  const toSkip = [];
  const notYet = [];

  // Earliest slots first: a backlog drains in schedule order.
  const ordered = rows
    .filter((r) => r && ACTIONABLE.has(String(r.status || '')))
    .slice()
    .sort((a, b) => String(a.scheduled_at || '').localeCompare(String(b.scheduled_at || '')));

  for (const row of ordered) {
    const id = String(row.etsy_listing_id || '');
    const status = String(row.status || '');
    const attempts = Number(row.attempts) || 0;

    // --- retry gating for a row that already failed ------------------------
    if (status === 'failed') {
      if (attempts >= maxAttempts) {
        notYet.push({ row_id: row.id, etsy_listing_id: id,
          reason: 'retry_limit_reached', attempts, error: row.error || '' });
        continue;
      }
      const last = Date.parse(row.last_attempt_at || row.updatedAt || '');
      const waited = Number.isFinite(last) ? nowMs - last : Infinity;
      if (waited < retryDelayMinutes * 60_000) {
        notYet.push({ row_id: row.id, etsy_listing_id: id,
          reason: 'retry_delay_not_elapsed', attempts,
          minutes_remaining: Math.ceil((retryDelayMinutes * 60_000 - waited) / 60_000) });
        continue;
      }
    }

    // --- the item must still exist ----------------------------------------
    const item = itemById.get(id);
    if (!item) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'item_row_missing',
        error: `No items row for listing ${id}. It was removed, or the sync `
          + 'never produced it.' });
      continue;
    }

    // --- boards must still be enabled -------------------------------------
    const boards = parseList(item.board_slugs);
    if (!boards.some((b) => enabled.has(b))) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'skipped',
        reason: 'all_boards_disabled',
        error: `Every board for this listing is disabled (${boards.join(', ') || 'none'}).` });
      continue;
    }

    // --- there must be something to post ----------------------------------
    const image_url = String(item.image_url || '');
    if (!image_url) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'no_image', error: 'The items row has no image_url.' });
      continue;
    }
    const post_text = String(row.post_text || '');
    if (!post_text.trim()) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'no_post_text', error: 'The schedule row has an empty post_text.' });
      continue;
    }

    // --- immediate or scheduled? ------------------------------------------
    const slot = Date.parse(row.scheduled_at || '');
    if (!Number.isFinite(slot)) {
      toSkip.push({ row_id: row.id, etsy_listing_id: id, status: 'failed',
        reason: 'bad_scheduled_at',
        error: `scheduled_at is not a date: ${row.scheduled_at}` });
      continue;
    }

    const lead = slot - nowMs;
    if (lead > maxAheadMs) {
      // Beyond what Facebook will accept; a later run will pick it up.
      notYet.push({ row_id: row.id, etsy_listing_id: id,
        reason: 'beyond_facebook_scheduling_window',
        scheduled_at: row.scheduled_at,
        days_ahead: Math.round(lead / 86_400_000) });
      continue;
    }

    const mode = lead >= minLeadMs ? 'scheduled' : 'immediate';

    if (toPublish.length >= maxPerRun) {
      notYet.push({ row_id: row.id, etsy_listing_id: id,
        reason: 'max_publish_per_run', scheduled_at: row.scheduled_at });
      continue;
    }

    toPublish.push({
      row_id: row.id,
      etsy_listing_id: id,
      board_slug: row.board_slug || '',
      post_text,
      image_url,
      etsy_url: item.etsy_url || `https://www.etsy.com/listing/${id}`,
      scheduled_at: row.scheduled_at,
      mode,
      // Facebook wants whole seconds since the epoch, and only for a
      // scheduled post.
      scheduled_publish_time: mode === 'scheduled' ? Math.floor(slot / 1000) : null,
      attempts: attempts + 1,
      was_retry: status === 'failed',
    });
  }

  return {
    toPublish,
    toSkip,
    notYet,
    report: {
      actionable_rows: ordered.length,
      publishing: toPublish.length,
      scheduled: toPublish.filter((p) => p.mode === 'scheduled').length,
      immediate: toPublish.filter((p) => p.mode === 'immediate').length,
      retries: toPublish.filter((p) => p.was_retry).length,
      skipping: toSkip.length,
      deferred: notYet.length,
      skip_reasons: toSkip.reduce((a, s) => {
        a[s.reason] = (a[s.reason] || 0) + 1; return a;
      }, {}),
      defer_reasons: notYet.reduce((a, s) => {
        a[s.reason] = (a[s.reason] || 0) + 1; return a;
      }, {}),
    },
  };
}

/**
 * Turn a selection entry into the two Graph API calls.
 *
 * A scheduled photo post is a two-step operation: upload the photo
 * unpublished to get a media id, then create the feed post with that
 * attachment and the publish time. Posting the photo directly to /photos with
 * a scheduled time is not reliable across API versions.
 */
function buildGraphCalls(entry, { pageId, apiVersion = 'v21.0' } = {}) {
  if (!pageId) throw new Error('FB_PAGE_ID is not set in the config table.');
  const base = `https://graph.facebook.com/${apiVersion}`;
  return {
    photo: {
      url: `${base}/${pageId}/photos`,
      body: { url: entry.image_url, published: false },
    },
    // media_fbid is filled in once the upload returns.
    feed: {
      url: `${base}/${pageId}/feed`,
      body: {
        message: entry.post_text,
        published: entry.mode === 'scheduled' ? false : true,
        ...(entry.mode === 'scheduled'
          ? { scheduled_publish_time: entry.scheduled_publish_time } : {}),
      },
    },
  };
}

// ---------------------------------------------------------------- n8n glue
// Workflow C: decide what to publish, and how.
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const boards = $('Load Boards').all().map((i) => i.json || {}).filter((b) => b.board_slug);
const items = $('Load Items').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);
const rows = $('Load Queue').all().map((i) => i.json || {}).filter((r) => r.etsy_listing_id);

const enabledBoards = boards.filter((b) => b.enabled === true).map((b) => b.board_slug);
const nowMs = Date.now();

const plan = selectForPublish({
  rows,
  items,
  enabledBoards,
  nowMs,
  retryDelayMinutes: cfg._retry_delay_minutes,
  maxAttempts: 2,
  maxPerRun: cfg._max_publish,
});

// In live mode the Page id comes from the OAuth login itself, so the config
// key is optional. Pick Page does not run during a dry run.
const oauthPageId = (() => {
  try {
    const p = $('Pick Page').first().json;
    return p && p.ok ? String(p.page_id) : '';
  } catch {
    return '';
  }
})();

const realPageId = String(cfg.FB_PAGE_ID || '').trim() || oauthPageId;
const apiVersion = String(cfg.FB_API_VERSION || 'v21.0').trim();
const out = [];

// A dry run never calls Facebook, so it does not need a real Page id - and
// being able to validate the whole path BEFORE obtaining a token is the
// entire point of the dry run. The placeholder is obvious on sight in the
// logged URLs.
const pageId = realPageId || (cfg._dry_run ? 'FB_PAGE_ID_NOT_SET' : '');

// Outside a dry run, a missing Page id means nothing can be published. Say so
// once, rather than failing every row with an opaque HTTP error.
if (plan.toPublish.length && !pageId) {
  out.push({ json: {
    _kind: 'report',
    workflow: 'C - Publisher',
    level: 'error',
    context: 'publish_blocked',
    created_at: new Date(nowMs).toISOString(),
    ...plan.report,
    publishing: 0,
    note: 'FB_PAGE_ID is empty in the config table, so nothing was published. '
        + `${plan.toPublish.length} row(s) are ready and waiting. Either `
        + 'connect the "Facebook OAuth (login)" credential, which supplies '
        + 'the Page id automatically, or fill FB_PAGE_ID in the config table.',
  } });
  // Skip rows still get applied - a disabled board should not wait on a token.
  for (const s of plan.toSkip) out.push({ json: { _kind: 'skip', ...s } });
  return out;
}

for (const p of plan.toPublish) {
  const calls = buildGraphCalls(p, { pageId, apiVersion });
  out.push({ json: {
    _kind: 'publish',
    ...p,
    fb_photo_url: calls.photo.url,
    fb_feed_url: calls.feed.url,
    fb_published: calls.feed.body.published,
    fb_scheduled_publish_time: calls.feed.body.scheduled_publish_time ?? null,
    dry_run: cfg._dry_run,
  } });
}

for (const s of plan.toSkip) out.push({ json: { _kind: 'skip', ...s } });

out.push({ json: {
  _kind: 'report',
  workflow: 'C - Publisher',
  level: plan.toSkip.length ? 'warn' : 'info',
  context: 'publish_summary',
  created_at: new Date(nowMs).toISOString(),
  dry_run: cfg._dry_run,
  page_id_set: Boolean(realPageId),
  ...plan.report,
  deferred_examples: plan.notYet.slice(0, 5),
  note: cfg._dry_run
    ? 'DRY_RUN is on: nothing was sent to Facebook. The exact request bodies '
      + 'are in errors_log. Set DRY_RUN=false in config once the token is in.'
      + (realPageId ? '' : ' FB_PAGE_ID is still empty, so the logged URLs '
        + 'carry a placeholder.')
    : `Publishing ${plan.report.publishing} post(s): `
      + `${plan.report.scheduled} handed to Facebook as scheduled, `
      + `${plan.report.immediate} published immediately.`,
} });

return out;

// Confirms the atomic claim actually took.
//
// "Claim Row" updates the row only when its status is still the one we read,
// so if another run (or a second trigger firing) got there first, zero rows
// change. That is the double-post guard: without a confirmed claim we do not
// call Facebook at all.
// Mode: Run Once for All Items.

const entry = $('Loop Publish').first().json;
const updated = $input.all().map((i) => i.json || {}).filter((r) => r && r.id);

const claimed = updated.length > 0;

return [{ json: {
  ...entry,
  claimed,
  claim_note: claimed
    ? `Row ${entry.row_id} claimed (status -> posting).`
    : `Row ${entry.row_id} was NOT claimed - its status changed since it was `
      + 'read, so another run owns it. Skipping to avoid a double post.',
} }];

// Reads the photo id from whichever upload path ran.
//
// The URL upload is tried first. If Facebook cannot fetch the image itself
// (Pinterest hotlink protection, for example) the binary path downloads the
// bytes in n8n and uploads them as a file instead.
// Mode: Run Once for All Items.

const entry = $('Verify Claim').first().json;

const idFrom = (nodeName) => {
  try {
    const j = $(nodeName).first().json || {};
    // Graph returns { id } for an unpublished photo. With fullResponse the
    // payload sits under .body.
    const body = j.body && typeof j.body === 'object' ? j.body : j;
    return body && body.id ? String(body.id) : '';
  } catch {
    return ''; // node did not run
  }
};

const viaUrl = idFrom('FB Upload Photo By URL');
const viaBinary = idFrom('FB Upload Photo Binary');
const media_fbid = viaUrl || viaBinary;

if (!media_fbid) {
  return [{ json: { ...entry, media_fbid: '', upload_path: 'none',
    upload_error: 'Neither the URL upload nor the binary upload returned a '
      + 'photo id. See the two FB Upload nodes in this execution.' } }];
}

return [{ json: {
  ...entry,
  media_fbid,
  upload_path: viaUrl ? 'url' : 'binary',
  upload_error: '',
} }];

// Maps the Graph API response onto the schedule row update.
// Mode: Run Once for All Items.

const entry = $('Media Id').first().json;
const nowIso = new Date().toISOString();

const res = $input.first().json || {};
const body = res.body && typeof res.body === 'object' ? res.body : res;
const httpStatus = res.statusCode ?? null;

// Graph returns { id: "<page>_<post>" } on success, or { error: {...} }.
