// ------------------------------------------------------------------- public

function parsePin(item, opts = {}) {
  const pin_url = extractPinUrl(item);
  const etsy = extractEtsy(item);
  if (!etsy) {
    return { ok: false, reason: 'no_etsy_link', pin_url,
             title: cleanText(item.title).slice(0, 120) };
  }
  const rawImage = extractImage(item);
  const cands = imageCandidates(rawImage);
  const title = cleanText(item.title);
  const description = cleanText(
    item.description || item.content || item['content:encoded'] || item.summary || ''
  );
  if (!cands.length) {
    return { ok: false, reason: 'no_image', pin_url, title,
             etsy_listing_id: etsy.etsy_listing_id };
  }
  return {
    ok: true,
    etsy_listing_id: etsy.etsy_listing_id,
    etsy_url: etsy.etsy_url,
    title,
    description,
    image_url: cands[0],          // provisional; HEAD-verified downstream
    image_candidates: cands,
    pin_url,
    board_slug: opts.board_slug || '',
  };
}

/**
 * Pin page -> destination (Etsy) URL.
 *
 * Pinterest's board RSS does not publish a pin's outbound link (verified
 * against a real board: 26/26 pins had no destination URL anywhere in the
 * feed). The link only exists on the pin page itself, inside the embedded
 * JSON blob Pinterest ships for client-side hydration.
 *
 * Part of the Pinterest source layer. Everything here disappears if the
 * source is later swapped for the Etsy API.
 */

// ETSY_LISTING_RE is provided by the inlined pin-parser above.

/** Pin id from any pinterest pin URL form. */
function pinId(url) {
  const m = String(url || '').match(/\/pin\/(\d+)/);
  return m ? m[1] : '';
}

/**
 * Pinterest ships the pin's outbound URL under several JSON keys depending on
 * which renderer served the page. Ordered most- to least-specific; the first
 * that yields an Etsy listing wins.
 */
const JSON_LINK_KEYS = [
  'link',            // canonical destination on the Pin object
  'tracked_link',    // click-tracking wrapper, still contains the target
  'domain_url',
  'seo_canonical_url',
];

/**
 * Extract every plausible destination URL from a pin page's HTML.
 * Returns them in confidence order; callers pick the first Etsy listing.
 *
 * Works on the raw HTML string - no DOM, no browser. JSON string values are
 * escaped (\/), so unescape before matching.
 */
function destinationCandidates(html) {
  const s = String(html || '');
  const out = [];
  const push = (v) => {
    if (!v) return;
    const u = String(v).replace(/\\u002F/gi, '/').replace(/\\\//g, '/').trim();
    if (/^https?:\/\//i.test(u)) out.push(u);
  };

  // 1. Explicit JSON keys, e.g.  "link":"https:\/\/www.etsy.com\/listing\/123"
  for (const key of JSON_LINK_KEYS) {
    const re = new RegExp(`"${key}"\\s*:\\s*"((?:[^"\\\\]|\\\\.)*)"`, 'gi');
    for (const m of s.matchAll(re)) push(m[1]);
  }

  // 2. og:see_also / canonical-style meta tags sometimes carry the target.
  for (const m of s.matchAll(
    /<meta[^>]+(?:property|name)\s*=\s*["'](?:og:see_also|pinterest:link)["'][^>]+content\s*=\s*["']([^"']+)["']/gi
  )) push(m[1]);

  // 3. Last resort: any Etsy listing URL anywhere in the document, including
  //    inside escaped JSON. This is what actually survives Pinterest's
  //    frequent renderer changes.
  for (const m of s.matchAll(/https?:(?:\\u002F|\\\/|\/){2}(?:[a-z0-9-]+\.)?etsy\.com(?:\\u002F|\\\/|\/)[^"'\s<>\\]*(?:(?:\\u002F|\\\/|\/)[^"'\s<>\\]*)*/gi)) {
    push(m[0]);
  }

  const seen = new Set();
  return out.filter((u) => !seen.has(u) && seen.add(u));
}

/**
 * Resolve a pin page's HTML to an Etsy listing.
 * @returns {{ok:true, etsy_listing_id, etsy_url}|{ok:false, reason, diagnostics}}
 */
function resolveEtsyFromHtml(html, opts = {}) {
  const s = String(html || '');
  const diagnostics = diagnose(s);

  for (const cand of destinationCandidates(s)) {
    const m = cand.match(ETSY_LISTING_RE);
    if (m) {
      return {
        ok: true,
        etsy_listing_id: m[1],
        etsy_url: `https://www.etsy.com/listing/${m[1]}`,
        matched_from: cand.slice(0, 200),
      };
    }
  }

  // A non-Etsy destination is a legitimate outcome (pin points elsewhere),
  // and must be distinguished from "Pinterest blocked us".
  const anyDest = destinationCandidates(s).find((u) => !/pinterest\.|pinimg\./i.test(u));
  return {
    ok: false,
    reason: diagnostics.looks_blocked ? 'blocked_or_login_wall'
      : anyDest ? 'destination_not_etsy'
      : 'no_destination_found',
    sample_destination: anyDest ? anyDest.slice(0, 200) : '',
    diagnostics,
    pin_url: opts.pin_url || '',
  };
}

/** Cheap signals for telling a real pin page from a bot wall. */
function diagnose(html) {
  const s = String(html || '');
  return {
    html_bytes: s.length,
    has_pws_data: /__PWS_(?:DATA|INITIAL_PROPS)__/.test(s),
    has_pin_json: /"pin"\s*:\s*\{|"objectType"\s*:\s*"pin"/i.test(s),
    mentions_etsy: /etsy\.com/i.test(s),
    looks_blocked:
      s.length < 20000
      || /captcha|are you a robot|unusual traffic/i.test(s)
      || (/log ?in to (?:see|continue)/i.test(s) && !/__PWS_/.test(s)),
  };
}

// ---------------------------------------------------------------- n8n glue
// Phase 2: turn fetched pin pages into `pins` row updates.
//
// Input: one item per fetched pin page (HTTP Request, responseFormat=text,
// fullResponse, neverError). Pairing back to the pin is done by index, which
// is safe because the HTTP node emits exactly one item per input item.
// Mode: Run Once for All Items.

const pending = $('Pins To Resolve').all().map((i) => i.json);
const cfg = $('Config').first().json;
const maxAttempts = cfg._resolve_max_attempts;
const now = new Date().toISOString();

const out = [];
const all = $input.all();

for (let i = 0; i < all.length; i++) {
  const j = all[i].json || {};
  const pin = pending[i] || {};
  const pin_id = pin.pin_id || '';
  const attempts = (Number(pin.resolve_attempts) || 0) + 1;

  const html = typeof j.data === 'string' ? j.data
    : typeof j.body === 'string' ? j.body : '';
  const status = j.statusCode ?? null;

  let update;
  if (!html) {
    update = {
      resolve_status: attempts >= maxAttempts ? 'failed' : 'new',
      resolve_error: `empty response (http ${status ?? 'n/a'})`,
    };
  } else {
    const r = resolveEtsyFromHtml(html, { pin_url: pin.pin_url });
    if (r.ok) {
      update = {
        etsy_listing_id: r.etsy_listing_id,
        resolve_status: 'ok',
        resolve_error: '',
        resolved_at: now,
      };
    } else if (r.reason === 'destination_not_etsy') {
      // A pin pointing somewhere other than Etsy is a permanent outcome, not
      // a failure to retry.
      update = { resolve_status: 'not_etsy', resolve_error: r.sample_destination || '' };
    } else {
      update = {
        resolve_status: attempts >= maxAttempts ? 'failed' : 'new',
        resolve_error: `${r.reason} (http ${status ?? 'n/a'}, `
          + `${r.diagnostics?.html_bytes ?? 0} bytes)`,
      };
    }
  }

  out.push({ json: {
    pin_id,
    pin_url: pin.pin_url || '',
    board_slug: pin.board_slug || '',
    resolve_attempts: attempts,
    etsy_listing_id: update.etsy_listing_id ?? (pin.etsy_listing_id || ''),
    resolved_at: update.resolved_at ?? pin.resolved_at ?? null,
    resolve_status: update.resolve_status,
    resolve_error: String(update.resolve_error || '').slice(0, 500),
    http_status: status,
  } });
}

return out;

// Phase 3: collapse resolved pins into one work item per Etsy listing.
//
// A listing pinned on several boards must produce ONE items row carrying all
// its board_slugs, never a duplicate per board - that is the whole point of
// keying on etsy_listing_id. Mode: Run Once for All Items.

const byListing = new Map();

for (const item of $input.all()) {
  const p = item.json || {};
  if (p.resolve_status !== 'ok' || !p.etsy_listing_id) continue;

  const id = String(p.etsy_listing_id);
  const cur = byListing.get(id) || {
    etsy_listing_id: id,
    etsy_url: `https://www.etsy.com/listing/${id}`,
    title: '',
    description: '',
    image_url: '',
    image_candidates: [],
    board_slugs: [],
    pin_urls: [],
  };

  // Prefer the richest text across the pins pointing at this listing.
  const t = String(p.title || '');
  const d = String(p.description || '');
  if (t.length > cur.title.length) cur.title = t;
  if (d.length > cur.description.length) cur.description = d;

  if (!cur.image_url && p.image_url) cur.image_url = String(p.image_url);
  if (!cur.image_candidates.length && p.image_candidates) {
    try {
      const c = typeof p.image_candidates === 'string'
        ? JSON.parse(p.image_candidates) : p.image_candidates;
      if (Array.isArray(c)) cur.image_candidates = c;
    } catch { /* keep empty; image_url still set */ }
  }
  if (p.board_slug && !cur.board_slugs.includes(p.board_slug)) cur.board_slugs.push(p.board_slug);
  if (p.pin_url && !cur.pin_urls.includes(p.pin_url)) cur.pin_urls.push(p.pin_url);

  byListing.set(id, cur);
}

const out = [...byListing.values()];
if (!out.length) {
  return [{ json: { _kind: 'none', message: 'No newly resolved listings this run.' } }];
}

// Expose an explicit candidate ladder for the HEAD-check chain downstream.
//
// Measured against real pins: /originals/*.jpg often 403s (hotlink
// protection, or the original is simply a PNG), /originals/*.png returns the
// true original (~850KB), and /1200x/ and /736x/ are byte-identical
// (~110KB). So three checks are worth making; the fourth is the safety net.
// Gaps are filled with the last known candidate so every slot is a real URL.
return out.map((v) => {
  const c = v.image_candidates.length ? v.image_candidates : [v.image_url].filter(Boolean);
  const at = (i) => c[i] || c[c.length - 1] || v.image_url || '';
  return { json: { _kind: 'listing', ...v,
    image_c1: at(0),
    image_c2: at(1),
    image_c3: at(2),
    image_c4: at(3),
  } };
});

// Phase 3: merge this listing with the items row that may already exist.
//
// Data tables have no UNIQUE constraint, so "never create a duplicate" is
// enforced here plus the upsert filter on etsy_listing_id. Merging is additive:
// a listing pinned on a new board gains that slug and keeps the old ones.
// Mode: Run Once for All Items.

const listing = $('Loop Listings').first().json;
const now = new Date().toISOString();

// "Get Existing Item" has alwaysOutputData, so a miss arrives as an item with
// no etsy_listing_id rather than as zero items.
const existingRows = $input.all()
  .map((i) => i.json || {})
  .filter((r) => r.etsy_listing_id);
const existing = existingRows[0] || null;

const parseList = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string' && v.trim()) {
    try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch { return []; }
  }
  return [];
};

const mergeUnique = (a, b) => {
  const out = [];
  const seen = new Set();
  for (const v of [...a, ...b]) {
    const s = String(v || '').trim();
    if (s && !seen.has(s)) { seen.add(s); out.push(s); }
  }
  return out;
};

const board_slugs = mergeUnique(parseList(existing?.board_slugs), listing.board_slugs);
const pin_urls = mergeUnique(parseList(existing?.pin_urls), listing.pin_urls);

return [{ json: {
  row_id: existing?.id ?? null,
  is_new: !existing,
  etsy_listing_id: listing.etsy_listing_id,
  etsy_url: listing.etsy_url,
  // Keep existing text if the new pin has less to say.
  title: (listing.title || '').length > String(existing?.title || '').length
    ? listing.title : String(existing?.title || ''),
  description: (listing.description || '').length > String(existing?.description || '').length
    ? listing.description : String(existing?.description || ''),
  board_slugs: JSON.stringify(board_slugs),
  pin_urls: JSON.stringify(pin_urls),
  first_seen_at: existing?.first_seen_at || now,
  last_seen_at: now,
  // Carried through for the image HEAD checks downstream.
  image_c1: listing.image_c1,
  image_c2: listing.image_c2,
  image_c3: listing.image_c3,
  image_c4: listing.image_c4,
  existing_image_url: String(existing?.image_url || ''),
} }];

// Phase 3: choose the highest-resolution image URL that actually loads.
//
// Three HEAD checks run unconditionally - they carry no body, and newly
// resolved listings are rare. Measured on real pins:
//   /originals/*.jpg  often 403 (hotlink protection, or original is a PNG)
//   /originals/*.png  200, the true original (~850KB)
//   /1200x/*.jpg      200 (~110KB, byte-identical to /736x/)
// Whichever answers 200 first wins. If none do we keep the last candidate
// anyway: Workflow C can still publish it by downloading the bytes and
// uploading them to Facebook as a file.
// Mode: Run Once for All Items.

const merged = $('Merge Item').first().json;

const statusOf = (nodeName) => {
  try {
    return ($(nodeName).first().json || {}).statusCode ?? null;
  } catch {
    return null; // node did not run
  }
};

const ladder = [
  { url: merged.image_c1, status: statusOf('Verify Image 1'), label: 'originals-jpg' },
  { url: merged.image_c2, status: statusOf('Verify Image 2'), label: 'originals-png' },
  { url: merged.image_c3, status: statusOf('Verify Image 3'), label: '1200x' },
];

const hit = ladder.find((c) => c.status === 200 && c.url);

const image_url = hit ? hit.url
  : (merged.image_c4 || merged.existing_image_url || merged.image_c1 || '');

const image_check = hit
  ? `${hit.label} 200`
  : ladder.map((c) => `${c.label} ${c.status ?? 'n/a'}`).join(', ')
    + ' - unverified, Workflow C will upload the bytes instead';

return [{ json: {
  etsy_listing_id: merged.etsy_listing_id,
  etsy_url: merged.etsy_url,
  title: merged.title,
  description: merged.description,
  image_url,
  board_slugs: merged.board_slugs,
  pin_urls: merged.pin_urls,
  first_seen_at: merged.first_seen_at,
  last_seen_at: merged.last_seen_at,
  _is_new: merged.is_new,
  _image_check: image_check,
} }];

// Final report for a sync run. Reads the phase nodes rather than recomputing,
// and tolerates phases that did not run (no boards, nothing to resolve).
// Mode: Run Once for All Items.

const safe = (name, fn, dflt) => {
  try { return fn($(name).all().map((i) => i.json || {})); } catch { return dflt; }
};

const boards = safe('Boards To Sync', (r) => r.filter((x) => x._kind === 'board'), []);
const resolved = safe('Resolve Pin Result', (r) => r, []);
const listings = safe('Group By Listing', (r) => r.filter((x) => x._kind === 'listing'), []);
const attempted = safe('Pins To Resolve', (r) => r.filter((x) => x._kind !== 'none'), []);

const byStatus = resolved.reduce((a, r) => {
  const k = r.resolve_status || 'unknown';
  a[k] = (a[k] || 0) + 1;
  return a;
}, {});

return [{ json: {
  workflow: 'A - Sync Boards',
  finished_at: new Date().toISOString(),
  boards_synced: boards.length,
  boards: boards.map((b) => b.board_slug),
  pins_resolve_attempted: attempted.length,
  resolve_outcomes: byStatus,
  listings_upserted: listings.length,
  listings: listings.map((l) => ({
    etsy_listing_id: l.etsy_listing_id,
    title: String(l.title || '').slice(0, 70),
  })),
  note: attempted.length >= ($('Config').first().json._resolve_max || 10)
    ? 'Hit PIN_RESOLVE_MAX_PER_RUN - more pins remain queued for the next run.'
    : 'All known pins have been processed.',
} }];

// Flattens the config table into one object so later nodes can read settings
// as $('Config').first().json.SLOTS instead of searching rows.
// Defaults are applied for any key missing from the table, so the workflow
// still runs on a fresh install. Mode: Run Once for All Items.

const DEFAULTS = {
  TIMEZONE: 'Europe/Belgrade',
  SLOTS: '10:00,15:00,20:00',
  TEXT_MODE: 'pinterest',
  REPOST_AFTER_DAYS: '60',
  SCHEDULE_HORIZON_DAYS: '14',
  MAX_QUEUE_PER_RUN: '60',
  RETRY_DELAY_MINUTES: '30',
  EXTRA_HASHTAGS: '',
  POST_TEXT_MAX_CHARS: '600',
  FB_PAGE_ID: '',
  PIN_RESOLVE_MAX_PER_RUN: '10',
  RESOLVE_THROTTLE_MS: '2000',
  RESOLVE_MAX_ATTEMPTS: '3',
  DRY_RUN: 'true',
  MAX_PUBLISH_PER_RUN: '20',
  FB_API_VERSION: 'v21.0',
  AUTH_MODE: 'oauth',
};

const cfg = { ...DEFAULTS };
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.key) cfg[String(r.key)] = r.value == null ? '' : String(r.value);
}

// Typed views, so consumers never re-parse strings.
cfg._slots = String(cfg.SLOTS).split(',').map((s) => s.trim()).filter(Boolean);
cfg._repost_after_days = Number(cfg.REPOST_AFTER_DAYS) || 0;
cfg._resolve_max = Math.max(1, Number(cfg.PIN_RESOLVE_MAX_PER_RUN) || 10);
cfg._throttle_ms = Math.max(0, Number(cfg.RESOLVE_THROTTLE_MS) || 0);
cfg._resolve_max_attempts = Math.max(1, Number(cfg.RESOLVE_MAX_ATTEMPTS) || 3);
cfg._horizon_days = Math.max(1, Number(cfg.SCHEDULE_HORIZON_DAYS) || 14);
cfg._max_queue = Math.max(1, Number(cfg.MAX_QUEUE_PER_RUN) || 60);
cfg._text_max = Math.max(80, Number(cfg.POST_TEXT_MAX_CHARS) || 600);
cfg._retry_delay_minutes = Math.max(1, Number(cfg.RETRY_DELAY_MINUTES) || 30);
cfg._max_publish = Math.max(1, Number(cfg.MAX_PUBLISH_PER_RUN) || 20);
// Anything but an explicit "false" keeps the safety on.
cfg._dry_run = String(cfg.DRY_RUN).trim().toLowerCase() !== 'false';
// Anything other than an explicit "token" means the OAuth login path.
cfg._auth_mode = String(cfg.AUTH_MODE).trim().toLowerCase() === 'token'
  ? 'token' : 'oauth';

return [{ json: cfg }];

// Resolves the Page and its access token at run time.
//
// The OAuth credential holds a USER token (that is what the login dialog
// grants). Posting to a Page needs a PAGE token, which /me/accounts derives
// from it. Doing that on every run means:
//   - no token is ever copied by hand or stored in the config table
//   - a Page token derived from a long-lived user token does not expire
//   - FB_PAGE_ID becomes optional when the account manages one Page
// Mode: Run Once for All Items.

const cfg = $('Config').first().json;
const mode = cfg._auth_mode; // 'oauth' | 'token'

// The remedy differs per mode, so hints name the thing the user actually has.
const reconnect = mode === 'oauth'
  ? 'Open Credentials -> "Facebook OAuth (login)", fill in App ID and App '
    + 'Secret, then click "Connect my account" and approve the Facebook window.'
  : 'Open Credentials -> "Facebook User Token" and paste a valid long-lived '
    + 'USER token (Graph API Explorer gives you one; see '
    + 'docs/facebook-page-token.md).';
const res = $input.first().json || {};
const body = res.body && typeof res.body === 'object' ? res.body : res;
const httpStatus = res.statusCode ?? null;

// Two different failures arrive here and must not be conflated:
//
//  1. n8n could not even send the request - almost always because the OAuth
//     credential has never been connected. The node then emits { error: ... }
//     with no statusCode, and the error object often serializes to {}.
//  2. Facebook answered with a Graph error, which has type/code/message.
const hasGraphError = body && body.error
  && (body.error.message || body.error.type || body.error.code !== undefined);

if (httpStatus == null && !hasGraphError) {
  const raw = res.error ?? body?.error;
  const detail = raw && (raw.message || raw.description || raw.reason);
  return [{ json: {
    ok: false,
    stage: 'request_not_sent',
    error: 'The call to /me/accounts never reached Facebook'
      + (detail ? `: ${detail}` : '.'),
    hint: `AUTH_MODE is "${mode}", and its credential is not usable yet. `
        + reconnect + ' Re-run afterwards.',
    http_status: null,
  } }];
}

if (hasGraphError) {
  const e = body.error;
  const parts = [e.type || 'GraphError', e.code !== undefined ? `(${e.code})` : '']
    .filter(Boolean).join(' ');
  return [{ json: {
    ok: false,
    stage: 'me_accounts_failed',
    error: `${parts}: ${e.message || 'no message returned'}`
      + (e.error_user_msg ? ` - ${e.error_user_msg}` : ''),
    hint: e.code === 190
      ? 'The token has expired or been revoked. ' + reconnect
      : 'Check that pages_show_list, pages_manage_posts and '
        + 'pages_read_engagement were all granted. '
        + (mode === 'token'
          ? 'Note: this must be a USER token, not a Page token - /me/accounts '
            + 'is what turns one into the other.'
          : ''),
    http_status: httpStatus,
  } }];
}

const pages = Array.isArray(body && body.data) ? body.data : [];

if (!pages.length) {
  return [{ json: {
    ok: false,
    stage: 'no_pages',
    error: 'The logged-in account manages no Pages that this app can see.',
    hint: 'You must be an admin of the Page, and the login must have granted '
        + 'pages_show_list.',
    http_status: httpStatus,
  } }];
}

const wanted = String(cfg.FB_PAGE_ID || '').trim();
let page = null;

if (wanted) {
  page = pages.find((p) => String(p.id) === wanted) || null;
  if (!page) {
    return [{ json: {
      ok: false,
      stage: 'page_id_not_found',
      error: `FB_PAGE_ID is ${wanted}, but the logged-in account does not `
        + 'manage a Page with that id.',
      pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
      hint: 'Fix FB_PAGE_ID in the config table, or clear it if the account '
          + 'manages exactly one Page.',
      http_status: httpStatus,
    } }];
  }
} else if (pages.length === 1) {
  page = pages[0];
} else {
  return [{ json: {
    ok: false,
    stage: 'page_id_required',
    error: `The account manages ${pages.length} Pages, so FB_PAGE_ID must say `
      + 'which one to post to.',
    pages_available: pages.map((p) => ({ id: p.id, name: p.name })),
    http_status: httpStatus,
  } }];
}

if (!page.access_token) {
  return [{ json: {
    ok: false,
    stage: 'no_page_token',
    error: `Page ${page.id} came back without an access_token.`,
    hint: 'The login did not grant pages_manage_posts for this Page.',
  } }];
}

return [{ json: {
  ok: true,
  page_id: String(page.id),
  page_name: String(page.name || ''),
  // Used as a request header by the publish nodes. Never written to a table.
  page_token: String(page.access_token),
  page_id_source: wanted ? 'config' : 'only_page_on_account',
  auth_mode: mode,
  pages_available: pages.length,
} }];

// Reports the outcome WITHOUT ever echoing the Page token.
// Mode: Run Once for All Items.

const r = $input.first().json || {};
const cfg = $('Config').first().json;

if (!r.ok) {
  return [{ json: {
    verdict: 'NOT WORKING',
    auth_mode: cfg._auth_mode,
    stage: r.stage, error: r.error, hint: r.hint,
    pages_available: r.pages_available,
  } }];
}

return [{ json: {
  verdict: 'WORKING',
  auth_mode: cfg._auth_mode,
  page_id: r.page_id,
  page_name: r.page_name,
  page_id_source: r.page_id_source,
  pages_on_account: r.pages_available,
  page_token_received: Boolean(r.page_token),
  next: cfg._dry_run
    ? 'Auth is fine. Set DRY_RUN=false in config to start publishing.'
    : 'Auth is fine and DRY_RUN is already off - C will publish on its next run.',
} }];

// Mode: Run Once for All Items. Names and counts only - no tokens.
const body=(n)=>{try{const j=$(n).first().json;return j&&j.body!==undefined?j.body:j;}catch{return null;}};
const status=(n)=>{try{return $(n).first().json.statusCode;}catch{return null;}};
const me=body('Me'), perm=body('Permissions'), acc=body('Accounts'), pg=body('Page');
const granted=(perm&&perm.data||[]).filter(p=>p.status==='granted').map(p=>p.permission);
const declined=(perm&&perm.data||[]).filter(p=>p.status!=='granted').map(p=>p.permission+':'+p.status);
const accErr=(acc&&acc.error)?(acc.error.type+' '+(acc.error.code||'')+': '+acc.error.message):null;
return [{json:{
  me_name:me&&me.name, me_id:me&&me.id,
  granted_permissions:granted,
  declined_or_missing:declined,
  accounts_status:status('Accounts'),
  accounts_error:accErr,
  pages_count:(acc&&Array.isArray(acc.data))?acc.data.length:'n/a',
  page_names:(acc&&acc.data||[]).map(p=>p.name),
  page_tasks:(acc&&acc.data||[]).map(p=>({name:p.name,tasks:p.tasks})),
  page_status:status('Page'),
  page_direct:(pg&&pg.error)?('ERR '+pg.error.code+' '+pg.error.message):(pg&&pg.name),
}}];

/**
 * Board input normalization: turn whatever the user types into a username,
 * a board slug and an RSS URL.
 *
 * Used by the feed probe and by Workflow D's "add board" form, so a board
 * added through the UI and a board tested by hand always produce the same
 * rss_url. Part of the Pinterest source layer.
 *
 * The forms accept sloppy input on purpose - a pasted board URL, a profile
 * URL, an @handle, a display name - because the user fills them in by hand.
 */

const PINTEREST_HOST_RE = /^https?:\/\/(?:[a-z0-9-]+\.)?pinterest\.[a-z.]+\//i;

/** "@SmartlyDigit", "pinterest.com/smartlydigit/", "SmartlyDigit" -> "smartlydigit" */
function normalizeUsername(input) {
  let s = String(input || '').trim();
  if (!s) return '';
  if (PINTEREST_HOST_RE.test(s)) {
    const m = s.replace(PINTEREST_HOST_RE, '').split(/[/?#]/).filter(Boolean);
    s = m[0] || '';
  }
  s = s.replace(/^@/, '').trim().toLowerCase();
  // Pinterest usernames: letters, digits, underscore; no spaces.
  s = s.replace(/[^a-z0-9_]/g, '');
  return s;
}

/** "Printable Wall Art!" -> "printable-wall-art"; already-slug passes through. */
function slugify(input) {
  return String(input || '')
    .trim()
    .toLowerCase()
    .replace(/&/g, ' and ')
    .replace(/['’]/g, '')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 80);
}

/**
 * Pull username and/or slug out of a pasted Pinterest URL.
 * Returns {} when the string is not a Pinterest URL.
 */
function fromPinterestUrl(input) {
  const s = String(input || '').trim();
  if (!PINTEREST_HOST_RE.test(s)) return {};
  const parts = s.replace(PINTEREST_HOST_RE, '').split(/[?#]/)[0]
    .split('/').filter(Boolean);
  if (!parts.length) return {};
  const out = { username: normalizeUsername(parts[0]) };
  if (parts[1]) {
    // Tolerate a pasted ".../board.rss" too.
    out.board_slug = slugify(parts[1].replace(/\.rss$/i, ''));
  }
  // /pin/12345/ is a pin, not a board - do not mistake it for a slug.
  if (out.board_slug === 'pin' || /^\d+$/.test(out.board_slug || '')) {
    delete out.board_slug;
  }
  return out;
}

